const SPEC_VALUE_SAFE_RE = /^[a-zA-Z0-9\s#%.,()'"/_-]{1,256}$/;
const SPEC_VALUE_FORBIDDEN_RE = /url\s*\(|image-set\s*\(|element\s*\(|expression\s*\(|javascript:|\/\//i;
const isSafeSpecValue = (v: string) => SPEC_VALUE_SAFE_RE.test(v) && !SPEC_VALUE_FORBIDDEN_RE.test(v);


/** hex(#RGB/#RRGGBB)/rgb() → [r,g,b]. 그 외 형식은 null */
function parseRgb(cssColor: string): [number, number, number] | null {
  const v = cssColor.trim();
  const hex = v.match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i)?.[1];
  if (hex) {
    const h = hex.length === 3 ? hex.split('').map((c) => c + c).join('') : hex;
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)];
  }
  const m = v.match(/^rgba?\(\s*(\d{1,3})[,\s]+(\d{1,3})[,\s]+(\d{1,3})/i);
  if (!m) return null;
  return [Number(m[1]), Number(m[2]), Number(m[3])];
}

/* ── AI 구조화 문서 (designComponentAi 스키마와 쌍) ── */

interface ComponentDocData {
  summary: string;
  /** 언제·왜 쓰는지 (요약보다 긴 설명) */
  usage?: string;
  anatomy?: Array<{ part: string; detail?: string }>;
  props?: Array<{ name: string; type?: string; desc: string }>;
  variants?: Array<{ name: string; desc: string; preview?: { bg?: string; fg?: string; border?: string; accent?: string; height?: string; padding?: string; radius?: string; fontSize?: string } }>;
  do?: string[];
  dont?: string[];
  a11y?: string[];
  preview?: { kind: string; label?: string; sub?: string; icon?: string | null; width?: number; styleRef?: string };
}

const AI_DOC_MARK_TEXT = 'design-md: ai-doc';

/** usage_md 에서 구조화 문서 추출 — 실패하면 null (구버전 산문은 기존 경로로 렌더) */
function parseComponentDoc(usageMd: string | null | undefined): ComponentDocData | null {
  if (!usageMd || !usageMd.includes(AI_DOC_MARK_TEXT)) return null;
  const head = usageMd.split(/\n---\n/)[0].replace(/<!--[^>]*-->/g, '').trim();
  if (!head.startsWith('{')) return null;
  try {
    const d = JSON.parse(head) as ComponentDocData;
    return typeof d?.summary === 'string' ? d : null;
  } catch {
    return null;
  }
}

/** 미리보기 아이콘 — 인라인 SVG (외부 의존 없음) */
function DocIcon({ name, color }: { name: string; color: string }) {
  const common = { width: 16, height: 16, viewBox: '0 0 16 16', fill: 'none', stroke: color, strokeWidth: 1.8, strokeLinecap: 'round' as const, strokeLinejoin: 'round' as const };
  if (name === 'check') return <svg {...common}><path d="M3 8.5l3.5 3.5L13 5" /></svg>;
  if (name === 'close') return <svg {...common}><path d="M4 4l8 8M12 4l-8 8" /></svg>;
  if (name === 'chevron') return <svg {...common}><path d="M4 6l4 4 4-4" /></svg>;
  if (name === 'warn') return <svg {...common}><path d="M8 2.5L15 13.5H1z" /><path d="M8 7v3M8 12h.01" /></svg>;
  if (name === 'error') return <svg {...common}><circle cx="8" cy="8" r="6" /><path d="M8 5v4M8 11h.01" /></svg>;
  return <svg {...common}><circle cx="8" cy="8" r="6" /><path d="M8 7v4M8 5h.01" /></svg>;
}

