function LivePreviewButton({ base, hover, label, icon }: { base: React.CSSProperties; hover?: React.CSSProperties; label: string; icon?: React.ReactNode }) {
  const [h, setH] = useState(false);
  const [p, setP] = useState(false);
  return (
    <button
      type="button"
      onMouseEnter={() => setH(true)}
      onMouseLeave={() => { setH(false); setP(false); }}
      onMouseDown={() => setP(true)}
      onMouseUp={() => setP(false)}
      style={{
        border: 'none', cursor: 'pointer', fontFamily: 'inherit',
        transition: 'filter 0.15s, transform 0.08s, box-shadow 0.15s',
        ...base,
        ...(h ? (hover ?? { filter: 'brightness(0.93)' }) : null),
        transform: p ? 'scale(0.97)' : 'none',
      }}
    >
      {icon}
      {label}
    </button>
  );
}

