const ARCH_SHAPED = new Set<Archetype>(['checkbox', 'radio', 'toggle', 'tab', 'segment', 'input', 'cell']);

function LiveToggle({ w, h, radius, onBg, offBg, initialOn = true, disabled = false }: { w: number; h: number; radius: string | number; onBg: string; offBg: string; initialOn?: boolean; disabled?: boolean }) {
  const [on, setOn] = useState(initialOn);
  const thumb = Math.max(10, h - 6);
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      disabled={disabled}
      onClick={() => setOn((v) => !v)}
      style={{
        display: 'inline-flex', alignItems: 'center', justifyContent: on ? 'flex-end' : 'flex-start',
        width: w, height: h, padding: 3, boxSizing: 'border-box', borderRadius: radius,
        border: 'none', cursor: disabled ? 'not-allowed' : 'pointer', background: on ? onBg : offBg,
        opacity: disabled ? 0.5 : 1, transition: 'background-color 0.18s',
      }}
    >
      <span style={{ width: thumb, height: thumb, borderRadius: '50%', background: '#FFFFFF', boxShadow: '0 1px 2px rgba(0,0,0,0.3)' }} />
    </button>
  );
}

