/** RGB → HSL (0~1). 파싱 불가 형식은 null */
function toHsl(cssColor: string): { h: number; s: number; l: number } | null {
  const rgb = parseRgb(cssColor);
  if (!rgb) return null;
  const [r, g, b] = rgb.map((x) => x / 255);
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  if (d === 0) return { h: 0, s: 0, l };
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  const h = max === r ? ((g - b) / d + (g < b ? 6 : 0)) : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return { h: (h * 60) / 360, s, l };
}

/** 색 위에 얹을 글자색 — hex/rgb 만 휘도 계산, 그 외 형식은 null(호출부가 안전한 레이아웃로 강등) */
/** 그라디언트 등 복합 값에서 대표 색 하나를 뽑는다 — 대비 계산은 단색이어야 한다 */
function solidOf(v: string): string {
  return v.match(/#[0-9a-fA-F]{3,8}|rgba?\([^)]+\)/)?.[0] ?? v;
}

function readableOn(cssColor: string): string | null {
  const rgb = parseRgb(cssColor);
  if (!rgb) return null;
  const [r, g, b] = rgb;
  const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return lum > 0.62 ? '#111827' : '#FFFFFF';
}

/** 텍스트 위계용 알파 적용 (본문 100% / 보조 ~72% / 비활성 ~55%) — 파싱 불가 형식은 폴백 */
function withAlpha(cssColor: string, alpha: number, fb: string): string {
  const rgb = parseRgb(cssColor);
  return rgb ? `rgba(${rgb[0]}, ${rgb[1]}, ${rgb[2]}, ${alpha})` : fb;
}

/** WCAG 대비율 (1~21). 어느 한쪽이라도 파싱 불가면 null — 호출부가 휘도 클래스 휴리스틱으로 폴백 */
function contrast(a: string, b: string): number | null {
  const ra = parseRgb(a);
  const rb = parseRgb(b);
  if (!ra || !rb) return null;
  const lum = ([r, g, bl]: [number, number, number]) => {
    const lin = (c: number) => {
      const s = c / 255;
      return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
    };
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(bl);
  };
  const la = lum(ra);
  const lb = lum(rb);
  const [hi, lo] = la >= lb ? [la, lb] : [lb, la];
  return (hi + 0.05) / (lo + 0.05);
}

/**
 * 고채도 페이지 캔버스 완화 — 원색(HSL S>0.6)이 페이지 전체 배경이면 장시간 열람 피로
 * (실측: Discord blurple). 색상(hue)·명도는 유지하고 채도만 낮춘 톤을 반환.
 * 원색 자체는 스와치·컴포넌트 견본(토큰 원값 직접 사용)에서 그대로 노출된다.
 * 파싱 불가 형식·저채도는 원본 유지.
 */
function calmCanvas(cssColor: string): string {
  const rgb = parseRgb(cssColor);
  if (!rgb) return cssColor;
  const [r, g, b] = rgb.map((c) => c / 255);
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  if (d === 0) return cssColor;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  if (s <= 0.42) return cssColor;
  let h = 0;
  if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
  else if (max === g) h = ((b - r) / d + 2) / 6;
  else h = ((r - g) / d + 4) / 6;
  const s2 = 0.26 + (s - 0.42) * 0.15; // 초과분만 완만히 반영 → 0.26~0.35
  const hue2rgb = (p: number, q: number, t: number) => {
    let tt = t;
    if (tt < 0) tt += 1;
    if (tt > 1) tt -= 1;
    if (tt < 1 / 6) return p + (q - p) * 6 * tt;
    if (tt < 1 / 2) return q;
    if (tt < 2 / 3) return p + (q - p) * (2 / 3 - tt) * 6;
    return p;
  };
  const q = l < 0.5 ? l * (1 + s2) : l + s2 - l * s2;
  const p = 2 * l - q;
  const to255 = (t: number) => Math.round(hue2rgb(p, q, t) * 255);
  return `rgb(${to255(h + 1 / 3)}, ${to255(h)}, ${to255(h - 1 / 3)})`;
}

