const toPascal = (slug: string) =>
  slug.split('-').filter(Boolean).map((s) => s[0].toUpperCase() + s.slice(1)).join('');

function CopyButton({ text, label = '복사', border }: { text: string; label?: string; border: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      onClick={() => {
        navigator.clipboard?.writeText(text).then(() => {
          setCopied(true);
          setTimeout(() => setCopied(false), 1500);
        });
      }}
      style={{
        fontSize: 12, padding: '4px 10px', borderRadius: 8, border, cursor: 'pointer',
        background: copied ? 'rgba(22,163,74,0.15)' : 'transparent', color: 'inherit',
      }}
    >
      {copied ? '복사됨 ✓' : label}
    </button>
  );
}

function Md({ children }: { children: string }) {
  return (
    <div className="design-guide-md" style={{ fontSize: 13.5, lineHeight: 1.7 }}>
      <ReactMarkdown remarkPlugins={[remarkGfm]}>{children}</ReactMarkdown>
    </div>
  );
}

interface NavItem {
  id: string;
  label: string;
  /** 컴포넌트 그룹 안의 소분류 — 목록이 길어지면 역할별로 묶어 준다 */
  section?: string;
}

/**
 * 여러 컴포넌트를 한 문서에서 설명하는 산문을 조각으로 쪼갠다.
 * 실측 규약: 문단이 **`toast`** 처럼 컴포넌트 이름 코드로 시작한다.
 * 쪼개지 않으면 Toast·Popup·Tooltip 페이지가 이미 있는데도 같은 내용의 문서가
 * 목록에 하나 더 남는다.
 */
function splitDocByComponent(bodyMd: string): Array<{ key: string | null; text: string }> {
  const blocks = bodyMd.split(/\n{2,}/).map((b) => b.trim()).filter(Boolean);
  const out: Array<{ key: string | null; text: string }> = [];
  for (const b of blocks) {
    const m = b.match(/^\s*(?:[-*]\s*)?\*\*`?([a-z][a-z0-9-]{1,40})`?\*\*/);
    const last = out[out.length - 1];
    if (m) out.push({ key: m[1], text: b });
    else if (last && last.key) last.text += `\n\n${b}`; // 앞 조각의 연속 설명
    else out.push({ key: null, text: b });
  }
  return out;
}

/**
 * 컴포넌트 소분류 — 이름·제목 어디에나 걸리는 키워드로 역할을 판정한다.
 * 시스템마다 이름이 제각각이라(dark-pill-button · frap-floating-button · size-selector)
 * 접두 매칭으로는 못 묶는다. 순서가 우선순위.
 */
const COMPONENT_SECTIONS: Array<{ label: string; test: RegExp }> = [
  { label: '액션', test: /(button|btn|cta|fab|floating)/ },
  { label: '입력', test: /(input|field|search|select|checkbox|radio|toggle|switch|slider|picker|form|upload)/ },
  // tab(?!le) — 'table' 은 탐색이 아니라 표시다 (specArchetype 과 같은 처리)
  { label: '탐색', test: /(nav|tab(?!le)|segment|menu|sidebar|breadcrumb|pagination|filter|strip|link)/ },
  { label: '알림·오버레이', test: /(toast|popup|modal|dialog|tooltip|alert|snackbar|overlay|drawer|sheet|feedback|notification)/ },
  { label: '표시', test: /(card|list|table|badge|chip|tag|band|hero|banner|grid|block|surface|avatar|media|status|feature|editorial|content|reward|gift|thumbnail|pricing|tier|accordion|panel|day|swatch)/ },
];

/** 소분류 판정 — 어디에도 안 걸리면 '기타' */
function componentSection(name: string, title: string): string {
  const hay = `${name} ${title}`.toLowerCase();
  return COMPONENT_SECTIONS.find((sc) => sc.test.test(hay))?.label ?? '기타';
}

/** 소분류 정렬 순서 — 배열 순서대로, '기타' 는 항상 끝 */
function sectionRank(label: string): number {
  const i = COMPONENT_SECTIONS.findIndex((sc) => sc.label === label);
  return i === -1 ? COMPONENT_SECTIONS.length : i;
}
interface NavGroup {
  label: string;
  items: NavItem[];
}

export default function DesignGuideView({ system, tokens, themes, items, logo, previewDraft, overview, liveComponents }: Props) {
  const [dark, setDark] = useState(false);
  const logoSrc = (dark ? logo?.dark : logo?.light) ?? null;
  const active = useMemo(() => mergeTokens(tokens, dark ? themes.dark : undefined), [tokens, themes, dark]);

  /*
   * 활성 토큰을 CSS 변수로 실제 선언한다.
   *
   * 가이드 자신은 인라인 style 로 그리지만, 실물 컴포넌트(liveComponents)는
   * `var(--color-…)` 를 참조한다. 변수가 없으면 컴포넌트에 박아둔 폴백 hex 가
   * 그려져 "토큰을 쓴다" 는 전제가 거짓이 된다 — 리브랜딩도 다크 전환도 안 먹는다.
   *
   * dark 토글과 같은 `active` 를 쓰므로 테마 전환이 그대로 따라온다.
   */
  const tokenVars = useMemo(() => {
    const out: Record<string, string> = {};
    for (const [cat, map] of Object.entries(active)) {
      for (const [key, value] of Object.entries(map)) out[`--${cat}-${key}`] = value;
    }
    return out as React.CSSProperties;
  }, [active]);
  const scrollRef = useRef<HTMLDivElement>(null);

  // 상단 바 실측 높이 → CSS 변수(--dgv-topbar-h) — 사이드바 sticky top 과 쌍.
  // 하드코딩(58px)은 헤더 실높이(로고 유무·브랜드 폰트에 따라 가변)와 어긋나면
  // 스크롤 가능한 페이지에서만 sticky 가 스크롤 0에서도 클램프를 발동시켜
  // 사이드바가 헤더보다 아래로 밀림(스크롤 없는 페이지와 간격 불일치).
  const topbarRef = useRef<HTMLElement>(null);
  const [topbarH, setTopbarH] = useState(58);
  useEffect(() => {
    const el = topbarRef.current;
    if (!el) return;
    const apply = () => setTopbarH(Math.round(el.getBoundingClientRect().height));
    apply();
    const ro = new ResizeObserver(apply);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  // useMemo 필수 — 매 렌더 fresh 배열이면 navGroups useMemo 가 무효화되고, 인디케이터
  // measure effect(deps [activeId, navGroups])가 매 렌더 setState → 무한 재렌더 루프.
  /** 아직 구조화 문서가 안 붙은 컴포넌트 수 — 업로드 직후 AI 보강이 도는 동안 진행 표시로 쓴다 */
  const pendingDocCount = useMemo(
    () => items.filter((i) => i.kind === 'component' && !parseComponentDoc(i.usageMd)).length,
    [items],
  );
  /**
   * 보강이 멈췄는지 — 업로드 직후엔 백그라운드로 도는 중이라 '진행 중', 한참 지났는데도
   * 비어 있으면 실행이 안 됐거나 실패한 것이다. updatedAt 이 없으면(킷 셸) 판정하지 않는다.
   */
  const ENRICH_GRACE_MS = 6 * 60 * 1000;
  const enrichStalled = useMemo(() => {
    if (!system.updatedAt) return false;
    const t = Date.parse(system.updatedAt);
    return Number.isFinite(t) ? Date.now() - t > ENRICH_GRACE_MS : false;
  }, [system.updatedAt]);

  const components = useMemo(
    () => items.filter((i) => i.kind === 'component').sort((a, b) => a.position - b.position),
    [items],
  );
  const resources = useMemo(
    () => items.filter((i) => i.kind === 'resource').sort((a, b) => a.position - b.position),
    [items],
  );
  // 리소스 3분류 (컴포넌트 IA — 파운데이션과 동급 분리):
  // ① spec-components — frontmatter components: 맵의 스펙 (브랜드 컴포넌트 스펙 페이지)
  // ② 컴포넌트 문서 — 코드 없이 강등된 ## Components 산문 (compat 이 마커 삽입, 쌍 리터럴)
  // ③ 순수 참조 문서 — 나머지 (리소스 그룹 잔류)
  const COMPONENT_DOC_MARKER = '<!-- design-md: component-doc -->';
  /** design-md 내부 마커 주석 제거 — react-markdown 은 raw HTML 을 렌더하지 않아 텍스트로 새어 나온다 */
  const stripMarks = (md: string) => md.replace(/<!--\s*design-md:[^>]*-->/g, '').replace(/^\s+/, '').trimEnd();
  const specRes = useMemo(() => resources.find((r) => r.name === 'spec-components') ?? null, [resources]);
  const specEntries = useMemo(() => {
    const specRes = resources.find((r) => r.name === 'spec-components');
    return specRes?.bodyMd ? parseComponentSpecs(specRes.bodyMd) : [];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resources]);
  /**
   * 컴포넌트 문서 판정 — 3단 (마커 → 이름 아키타입 → 본문이 스펙 엔트리를 설명).
   * 마커는 compat 이 `## Components` 산문을 강등할 때만 붙으므로, 처음부터 `## Resources`
   * 에 컴포넌트 문서를 넣은 파일(폴라리스 등)까지 잡으려면 뒤 두 단이 필요하다.
   * 리소스 그룹에는 진짜 참조 문서만 남는다.
   */
  const isComponentDoc = (r: GuideItem): boolean => {
    if (r.name === 'spec-components') return false;
    const body = r.bodyMd ?? '';
    if (body.includes(COMPONENT_DOC_MARKER)) return true;
    if (specArchetype(r.name) !== 'other') return true;
    return specEntries.some((e) => body.includes(e.name));
  };
  const componentDocs = useMemo(
    () => resources.filter(isComponentDoc),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [resources, specEntries],
  );
  /**
   * 여러 컴포넌트를 묶어 설명하는 문서(Feedback = toast·popup·tooltip)를 조각내
   * 각 컴포넌트에 배정한다. 배정된 조각은 그 컴포넌트 페이지에서 보여주고, 문서
   * 페이지에는 남은 조각만 남긴다 — 남는 게 없으면 문서 항목 자체가 사라진다.
   */
  const docSplit = useMemo(() => {
    /** 컴포넌트 이름 → 그 컴포넌트를 설명하는 조각들 */
    const toComp = new Map<string, string[]>();
    /** 문서 이름 → 어디에도 배정되지 않은 조각들 */
    const leftover = new Map<string, string[]>();
    const compNames = components.map((c) => c.name);
    const findComp = (key: string): string | null =>
      compNames.find((n) => n === key)
        ?? compNames.find((n) => specArchetype(key) === n)
        ?? compNames.find((n) => key.startsWith(`${n}-`) || n.startsWith(`${key}-`))
        ?? null;

    for (const r of componentDocs) {
      const parts = splitDocByComponent(stripMarks(r.bodyMd ?? ''));
      const rest: string[] = [];
      for (const part of parts) {
        const comp = part.key ? findComp(part.key) : null;
        if (comp) toComp.set(comp, [...(toComp.get(comp) ?? []), part.text]);
        else rest.push(part.text);
      }
      leftover.set(r.name, rest);
    }
    return { toComp, leftover };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [componentDocs, components]);

  const pureResources = useMemo(
    () => resources.filter((r) => r.name !== 'spec-components' && !isComponentDoc(r)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [resources, specEntries],
  );
  /**
   * 스펙 엔트리 ↔ 컴포넌트 매칭 — 아키타입이 같거나(button-primary ↔ button),
   * 이름이 같거나 프리픽스가 맞을 때(select-lg ↔ select). 아키타입이 'other' 인
   * 컴포넌트(select·toast·popup 등)는 이름 매칭으로만 잡힌다.
   */
  /** 이 시스템에 실제로 있는 컴포넌트 이름 — base 컴포넌트가 존재하는지 판정에 쓴다 */
  const componentNameSet = useMemo(() => new Set(components.map((c) => c.name)), [components]);

  /*
   * 엔트리 ↔ 컴포넌트 매칭. base 이름의 컴포넌트가 있으면 **그것에만** 속한다.
   * 아키타입만 보면 icon-button40 이 Button 에도 딸려 들어가 크기·변형이 뒤섞인다.
   * base 컴포넌트가 없을 때(생성기가 아키타입 그룹으로 흡수한 경우)만 아키타입으로 맞춘다.
   */
  const matchesComponent = (entryName: string, compName: string): boolean => {
    const base = specBaseName(entryName);
    if (componentNameSet.has(base)) return base === compName;
    return specArchetype(entryName) === compName
      || entryName === compName
      || entryName.startsWith(`${compName}-`);
  };

  // 스펙 엔트리 → 컴포넌트 문서 배정 (첫 토큰 단수화 프리픽스 매칭 — buttons↔button-*,
  // search-surface↔search-*). 문서 순서대로 greedy 1회 배정 — 문서 페이지 상단 견본용.
  // 미배정 잔여는 '브랜드 컴포넌트 스펙' 페이지에서 전체 그리드로 노출.
  const specAssign = useMemo(() => {
    const byDoc = new Map<string, SpecEntry[]>();
    const unassigned: SpecEntry[] = [];
    const prefixOf = (name: string) => name.split('-')[0].replace(/s$/, '');
    for (const e of specEntries) {
      // 컴포넌트 상세(Properties·Specification)에 이미 나오면 잔여가 아니다
      if (components.some((c) => matchesComponent(e.name, c.name))) continue;
      const doc = componentDocs.find((d) => {
        const p = prefixOf(d.name);
        return e.name === p || e.name.startsWith(`${p}-`) || e.name === d.name || e.name.startsWith(`${d.name}-`);
      });
      if (doc) {
        const arr = byDoc.get(doc.name) ?? [];
        arr.push(e);
        byDoc.set(doc.name, arr);
      } else {
        unassigned.push(e);
      }
    }
    return { byDoc, unassigned };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [specEntries, componentDocs, components]);

  /** 토큰 조회 (미정의 시 중립 폴백 — 견본 마크업 전용) */
  const tk = (cat: string, key: string, fallback: string) => active[cat]?.[key] ?? fallback;
  /**
   * 시맨틱 별칭 체인 — 외부 생태계 네이밍(Ferrari 류: canvas/ink/body/hairline)도
   * 브랜드 무드로 해석한다. 별칭 없이 알려진 키만 보면 다크 캔버스 브랜드가
   * 중립 흰 배경으로 강등돼 무드가 통째로 사라진다 (실측: DESIGN-ferrari.md).
   */
  const colorAlias = (keys: string[], fb: string): string => {
    for (const k of keys) {
      const v = active.color?.[k];
      if (v) return v;
    }
    return fb;
  };

  const KNOWN = new Set(['color', 'typography', 'spacing', 'radius', 'shadow']);
  const otherCategories = Object.keys(active).filter((c) => !KNOWN.has(c)).sort();
  const hasDark = !!themes.dark && Object.keys(themes.dark).length > 0;

  /* ── 브랜드 팔레트 (전부 검증된 토큰 값 or 중립 폴백) ── */
  // primary 해석: 정확 키 → 접두 매칭(brand-green·accent-yellow 류 — 이름 강제 대신 관용) → 중립 폴백
  const primaryVal = (() => {
    const exact = colorAlias(['primary', 'brand', 'accent'], '');
    if (exact) return exact;
    const cands = sorted(active.color ?? {}).filter(([k]) => /^(primary|brand|accent)/.test(k));
    // 대표성 우선 — normal/base/default 가 있으면 그것, 없으면 변주 표시가 없는 것부터
    const rank = (k: string) =>
      (/(^|-)(normal|base|default|main)(-|$)/.test(k) ? 0 : 10)
      + (/(neutral|soft|light|weak|subtle|alt|hover|pressed|focus)/.test(k) ? 5 : 0);
    const best = [...cands].sort(([a], [b]) => rank(a) - rank(b))[0];
    return best?.[1] ?? '#2563EB';
  })();
  // 폰트: font-family-base 규약 키 → 아무 *font-family* 토큰 (role 기반 네이밍 폴백)
  const fontVal =
    tk('typography', 'font-family-base', '') ||
    (Object.entries(active.typography ?? {}).find(([k]) => k.includes('font-family'))?.[1] ?? 'inherit');
  const pv = {
    surface: colorAlias(['surface', 'background', 'bg', 'canvas'], dark ? '#0B1120' : '#FFFFFF'),
    surfaceMuted: colorAlias(['surface-muted', 'surface-elevated', 'canvas-elevated', 'surface-card', 'surface-soft'], dark ? '#1E293B' : '#F1F5F9'),
    text: colorAlias(['text', 'ink', 'foreground', 'body-strong'], dark ? '#E2E8F0' : '#0F172A'),
    textMuted: colorAlias(['text-muted', 'body', 'muted'], dark ? '#94A3B8' : '#64748B'), // 다크 폴백 별도 — AA 대비 확보
    primary: primaryVal,
    primaryHover: colorAlias(['primary-hover', 'primary-active'], primaryVal),
    borderC: colorAlias(['border', 'hairline', 'divider'], dark ? '#334155' : '#E2E8F0'),
    danger: colorAlias(['danger', 'error', 'semantic-error'], '#DC2626'),
    success: colorAlias(['success', 'semantic-success'], '#16A34A'),
    font: fontVal,
    radiusSm: tk('radius', 'sm', '8px'),
    radiusMd: tk('radius', 'md', '12px'),
    radiusLg: tk('radius', 'lg', '16px'),
    spacingSm: tk('spacing', 'sm', '8px'),
    spacingMd: tk('spacing', 'md', '16px'),
    spacingLg: tk('spacing', 'lg', '24px'),
    shadowCard: tk('shadow', 'card', '0 2px 8px rgba(15,23,42,0.08)'),
  };
  // 고채도 캔버스 완화 (디자인 피드백 2-2) — 스와치·견본은 토큰 원값을 직접 읽으므로 영향 없음
  pv.surface = calmCanvas(pv.surface);
  // on-primary 토큰이 있으면 우선 (Ferrari 류 명시 페어링), 없으면 휘도 계산
  const onPrimary = active.color?.['on-primary'] ?? readableOn(pv.primary) ?? '#FFFFFF';
  // 캔버스/글자 짝 세이프티 — themes.dark 가 배경만 덮는 부분 커버 등에서 캔버스와 글자가
  // 겹칠 때 교정. 판정은 실제 WCAG 대비율 (휘도 클래스 0.62 문턱은 Ferrari body #969696
  // 처럼 다크 캔버스 위에서 멀쩡히 읽히는 중간 회색까지 순수 흰색으로 뭉개 위계를 파괴했음).
  const surfOn = readableOn(pv.surface);
  if (surfOn) {
    const cText = contrast(pv.text, pv.surface);
    if (cText !== null ? cText < 3 : readableOn(pv.text) === surfOn) pv.text = surfOn;
    const cMuted = contrast(pv.textMuted, pv.surface);
    // 교정할 때도 순수 흰색이 아니라 72% 계층으로 — 본문과의 위계 유지 (디자인 피드백 2-1)
    if (cMuted !== null ? cMuted < 2.2 : readableOn(pv.textMuted) === surfOn) {
      pv.textMuted = withAlpha(surfOn, 0.72, surfOn);
    }
  }
  // 텍스트 위계 차등 (디자인 피드백 2-1) — 토큰이 본문과 보조를 시각적으로 같은 색
  // (전부 흰색 등, 대비 1.15:1 미만)으로 수렴시키면 위계 소실 → 보조는 본문의 ~72% 로 분리.
  // 문자열 동일성 비교는 '#FFFFFF' vs '#ffffff' 대소문자에 뚫림 — 반드시 대비율로 판정.
  const cTiers = contrast(pv.textMuted, pv.text);
  if (cTiers !== null && cTiers < 1.15) pv.textMuted = withAlpha(pv.text, 0.72, pv.textMuted);
  // 비활성·그룹 라벨 계층 (~55%)
  const textFaint = withAlpha(pv.text, 0.55, pv.textMuted);
  // surfaceMuted 위 글자색 — 별칭 체인이 다크 elevated 면(NVIDIA 류)을 잡아도 대비 보장
  const onMuted = readableOn(pv.surfaceMuted) ?? pv.text;
  const hair = `1px solid ${pv.borderC}`;
  /** 타이포에 쓰인 글꼴들이 이 브라우저에 실제로 있는지 — 스펙시먼 신뢰도 표시용 */
  const typoGroups = useMemo(() => groupTypography(active.typography ?? {}), [active]);
  const typoFamilies = useMemo(() => {
    // 글꼴 이름 → 대표 스택. 같은 글꼴의 스택 변형(폴백만 다른 값)은 하나로 합친다.
    const seen = new Map<string, string>();
    const add = (v?: string) => {
      if (!v) return;
      const name = primaryFontName(v);
      if (name && !seen.has(name)) seen.set(name, v);
    };
    for (const r of typoGroups.roles) add(r.props['font-family']);
    for (const sc of typoGroups.scales) if (sc.prop === 'font-family') sc.entries.forEach(([, v]) => add(v));
    return [...seen.values()];
  }, [typoGroups]);

  /* 피처 카드용 브랜드 색 후보 — 배경·글자·테두리 계열(별칭 포함) 제외, 최대 6개 */
  const featureColors = useMemo(() => {
    const skip = /^(surface|text|border|background|bg|canvas|ink|body|hairline|muted|on-|foreground|line|label|static|layer|interaction|fill|divider|separator)/;
    const entries = Object.entries(active.color ?? {}).filter(([k]) => !skip.test(k));
    /*
     * 팔레트는 '이 브랜드가 어떤 색을 쓰는가' 를 한눈에 보이는 자리다. 알파벳 순으로 앞에서
     * 자르면 accent-neutral(연한 변주)이 accent-normal(대표)보다 먼저 오고, starbucks 는
     * consent-agree-green 이 primary-house-green 을 밀어낸다. 역할 → 대표성 → 이름 순으로 본다.
     */
    // 상태색(성공·경고·오류)은 브랜드 팔레트에선 후순위 — bmw 처럼 브랜드색 이름이 특이한
    // 시스템(m-red·bmw-blue)에서 success/warning 이 대표 자리를 차지하는 걸 막는다.
    const paletteRank = (k: string) => { const r = colorFamilyRank(k); return r === 2 ? 6.5 : r; };
    const weight = (k: string) =>
      paletteRank(k) * 100
      + (/(^|-)(normal|base|default|main)(-|$)/.test(k) ? 0 : 10)
      + (/(neutral|soft|light|weak|subtle|alt|hover|pressed|focus)/.test(k) ? 5 : 0);
    const ordered = entries.sort(([a], [b]) => weight(a) - weight(b) || a.localeCompare(b, 'en-US'));
    const dedupe: Array<[string, string]> = [];
    for (const [k, v] of ordered) if (!dedupe.some(([, dv]) => dv === v)) dedupe.push([k, v]);

    const hueGap = (a: number, b: number) => { const d = Math.abs(a - b); return Math.min(d, 1 - d); };
    const picked: Array<[string, string]> = [];
    const pickedHue: number[] = [];
    const take = (e: [string, string], hue: number | null) => {
      picked.push(e);
      if (hue !== null) pickedHue.push(hue);
    };
    // 1차 — 채도 있고 색조가 겹치지 않는 색 (진짜 팔레트)
    for (const [k, v] of dedupe) {
      const hsl = toHsl(v);
      if (!hsl || hsl.s < 0.18 || hsl.l < 0.08 || hsl.l > 0.94) continue;
      if (pickedHue.some((h) => hueGap(h, hsl.h) < 0.05)) continue;
      take([k, v], hsl.h);
      if (picked.length >= 6) break;
    }
    // 2차 — 색조가 하나뿐인 브랜드(애플·xai)는 같은 색조의 톤 변주까지 허용
    if (picked.length < 3) {
      for (const [k, v] of dedupe) {
        if (picked.length >= 3) break;
        const hsl = toHsl(v);
        if (!hsl || hsl.s < 0.18) continue;
        if (!picked.some(([, pv2]) => pv2 === v)) take([k, v], null);
      }
    }
    // 3차 — 무채색 브랜드는 그대로라도 보여 준다
    if (picked.length === 0) picked.push(...dedupe.slice(0, 3));
    return picked;
  }, [active.color]);


  /**
   * 개요 H2 를 파운데이션 카테고리로 보낸다 — `## Colors` 산문과 색 스와치가 다른 페이지에
   * 흩어져 있으면 같은 주제를 두 번 읽게 된다. 매칭 안 되는 것(원칙·아이콘 등)은 소개에 남는다.
   */
  const OVERVIEW_TO_FOUNDATION: Array<[RegExp, string]> = [
    [/^(colors?|색상|컬러|palette|팔레트)\b/i, 'color'],
    [/^(typography|타이포|서체|font)\b/i, 'typography'],
    [/^(spacing|layout|간격|여백|레이아웃|grid)\b/i, 'spacing'],
    [/^(shapes?|radius|round|라운드|모서리)\b/i, 'radius'],
    [/^(elevation|shadow|그림자|깊이)\b/i, 'shadow'],
    [/^(motion|animation|모션|전환|애니메이션)\b/i, 'duration'],
  ];
  const foundationCatOf = (title: string): string | null => {
    const hit = OVERVIEW_TO_FOUNDATION.find(([re]) => re.test(title.trim()));
    // 그 카테고리 토큰이 실제로 있을 때만 옮긴다 — 없으면 갈 곳이 없어 사라진다
    return hit && active[hit[1]] && Object.keys(active[hit[1]]).length > 0 ? hit[1] : null;
  };

  /**
   * 규약 외 H2 산문(원칙·색 역할·모션 규약 등)을 섹션으로 쪼갠다.
   * 파서는 overview 로 보존하는데 화면에 내보내는 경로가 없어 통째로 묻혀 있었다.
   */
  const overviewSections = useMemo(() => {
    const md = (overview ?? '').trim();
    if (!md) return [] as Array<{ id: string; title: string; body: string }>;
    const out: Array<{ id: string; title: string; body: string }> = [];
    const seen = new Map<string, number>();
    let title = '';
    let buf: string[] = [];
    const flush = () => {
      const body = buf.join('\n').trim();
      if (!title && !body) return;
      const base = (title || '개요').toLowerCase().replace(/[^a-z0-9가-힣]+/g, '-').replace(/^-|-$/g, '') || 'section';
      const n = (seen.get(base) ?? 0) + 1;
      seen.set(base, n);
      out.push({ id: n > 1 ? base + '-' + n : base, title: title || '개요', body });
      buf = [];
    };
    let inFence = false;
    for (const line of md.split('\n')) {
      if (/^```/.test(line)) inFence = !inFence;
      const h2 = inFence ? null : line.match(/^##\s+(.+)$/);
      if (h2) {
        flush();
        title = h2[1].trim();
        continue;
      }
      buf.push(line);
    }
    flush();
    return out.filter((sec) => sec.body.length > 0);
  }, [overview]);

  /** 소개에 남길 섹션 — 파운데이션으로 간 것은 뺀다 */
  const introOverviewSections = overviewSections.filter((sec) => foundationCatOf(sec.title) === null);
  /** 파운데이션 페이지 상단에 얹을 산문 (해당 카테고리로 매칭된 개요 H2) */
  const overviewFor = (cat: string): React.ReactNode => {
    const secs = overviewSections.filter((sec) => foundationCatOf(sec.title) === cat);
    if (secs.length === 0) return null;
    return (
      <div style={{ ...panel, borderRadius: pv.radiusLg, padding: '6px 20px', margin: '34px 0 26px' }}>
        {secs.map((sec) => (
          <section key={sec.id} id={`ov-${sec.id}`} style={{ scrollMarginTop: 90 }}>
            <Md>{sec.body}</Md>
          </section>
        ))}
      </div>
    );
  };

  /* ── 사이드바 IA — 전부 데이터에서 자동 생성 (데이터 없는 메뉴는 안 생김) ── */
  const navGroups = useMemo<NavGroup[]>(() => {
    const groups: NavGroup[] = [{ label: '개요', items: [{ id: 'intro', label: '소개' }] }];
    if (logo?.light || logo?.dark) {
      groups.push({ label: '브랜드', items: [{ id: 'brand-logo', label: '로고' }] });
    }
    const foundation: NavItem[] = [];
    for (const cat of ['color', 'typography', 'spacing', 'radius', 'shadow']) {
      if (active[cat] && Object.keys(active[cat]).length > 0) {
        foundation.push({ id: `foundation-${cat}`, label: CATEGORY_LABEL[cat] });
      }
    }
    for (const cat of otherCategories) foundation.push({ id: `foundation-${cat}`, label: cat });
    groups.push({ label: '파운데이션', items: foundation });
    // 컴포넌트 — 파운데이션과 동급 그룹: 완성 코드 + (코드 없는) 컴포넌트 문서 + 브랜드 스펙
    const componentItems: NavItem[] = components.map((c) => ({
      id: `component-${c.name}`,
      label: c.title,
      section: componentSection(c.name, c.title),
    }));
    // 같은 이름의 컴포넌트가 있으면 그 문서는 컴포넌트 페이지 Guidelines 로 흡수됨 — 목록 중복 제거
    for (const r of componentDocs) {
      // 컴포넌트 페이지 Guidelines 와 동일 기준(아키타입) — 흡수된 문서는 목록에서 감춘다
      // 이름이 컴포넌트와 1:1 이거나, 조각이 전부 컴포넌트로 배정돼 남은 내용이 없을 때 흡수
      const leftover = docSplit.leftover.get(r.name) ?? [];
      const absorbed = components.some((c) => specArchetype(r.name) === c.name || r.name === c.name)
        || leftover.join('').trim().length === 0;
      if (!absorbed) {
        componentItems.push({ id: `resource-${r.name}`, label: r.title, section: componentSection(r.name, r.title) });
      }
    }
    if (specRes && specAssign.unassigned.length > 0) {
      componentItems.push({ id: 'resource-spec-components', label: '기타 스펙', section: '기타' });
    }
    if (componentItems.length > 0) {
      // 소분류 순서로 재배열 — 목록 순서가 곧 이전/다음 이동 순서라 역할끼리 붙어 있어야 한다.
      // 같은 소분류 안에서는 원래 순서(position) 유지.
      const ordered = componentItems
        .map((it, i) => ({ it, i }))
        .sort((a, b) => {
          const d = sectionRank(a.it.section ?? '기타') - sectionRank(b.it.section ?? '기타');
          return d !== 0 ? d : a.i - b.i;
        })
        .map(({ it }) => it);
      groups.push({ label: '컴포넌트', items: ordered });
    }
    const resourceItems: NavItem[] = pureResources.map((r) => ({ id: `resource-${r.name}`, label: r.title }));
    resourceItems.push({ id: 'downloads', label: '다운로드' });
    groups.push({ label: '리소스', items: resourceItems });
    return groups;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [active, components, resources, specRes, componentDocs, pureResources, specAssign, logo, docSplit]);

  const flatNav = useMemo(() => navGroups.flatMap((g) => g.items), [navGroups]);
  const [activeId, setActiveId] = useState('intro');

  // URL 해시 ↔ 섹션 동기화 (딥링크 + 뒤로가기)
  useEffect(() => {
    const apply = () => {
      let h = '';
      try {
        h = decodeURIComponent(window.location.hash.slice(1));
      } catch {
        return; // 잘못된 퍼센트 시퀀스(#% 등) — 없는 id 와 동일하게 무시 (크래시 방지)
      }
      if (h && flatNav.some((n) => n.id === h)) setActiveId(h);
    };
    apply();
    window.addEventListener('hashchange', apply);
    return () => window.removeEventListener('hashchange', apply);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const navigate = (id: string) => {
    setActiveId(id);
    try {
      window.location.hash = id; // 히스토리에 쌓여 뒤로가기 동작
    } catch {
      /* noop */
    }
    // 개요 하위 항목은 소개 페이지 안의 섹션 — 맨 위로 올리지 말고 그 자리로 데려간다
    if (id.startsWith('ov-')) {
      requestAnimationFrame(() => document.getElementById(id)?.scrollIntoView({ block: 'start' }));
      return;
    }
    scrollRef.current?.scrollTo({ top: 0 });
  };


  // LNB 활성 인디케이터 — 항목별 정적 배경 대신 단일 pill 이 실측 좌표로 이동(슬라이드 전환).
  // 좌표는 aside 기준 rect 차분 — offset 계열은 offsetParent 가 중간 positioned 조상(nav 등)으로
  // 바뀌면 그룹 상대값이 되어 깨진다. aside 내부 스크롤(overflow-y) 보정 포함. 리사이즈 시 재실측.
  // 모바일 가로 배치에서도 left/width 를 함께 실측·전환하므로 방향 무관.
  const sidebarRef = useRef<HTMLElement>(null);
  const navItemRefs = useRef<Record<string, HTMLButtonElement | null>>({});
  const [navIndicator, setNavIndicator] = useState<{ top: number; left: number; width: number; height: number } | null>(null);
  useEffect(() => {
    const measure = () => {
      const el = navItemRefs.current[activeId];
      const aside = sidebarRef.current;
      if (!el || !aside) {
        setNavIndicator(null);
        return;
      }
      const ar = aside.getBoundingClientRect();
      const er = el.getBoundingClientRect();
      const next = {
        top: Math.round(er.top - ar.top + aside.scrollTop),
        left: Math.round(er.left - ar.left + aside.scrollLeft),
        width: Math.round(er.width),
        height: Math.round(er.height),
      };
      // 값 동일 시 이전 객체 유지 — deps 재실행이 있어도 setState 가 재렌더를 만들지 않게 (루프 2차 방어)
      setNavIndicator((prev) =>
        prev && prev.top === next.top && prev.left === next.left && prev.width === next.width && prev.height === next.height
          ? prev
          : next,
      );
    };
    measure();
    window.addEventListener('resize', measure);
    return () => window.removeEventListener('resize', measure);
  }, [activeId, navGroups]);

  /* 섹션 크롬 */
  const overline: React.CSSProperties = {
    fontSize: 11.5, fontWeight: 700, letterSpacing: '0.12em', color: pv.textMuted, marginBottom: 6,
  };
  const h2Style: React.CSSProperties = { fontSize: 32, fontWeight: 800, margin: '0 0 8px', color: pv.text, letterSpacing: '-0.02em', lineHeight: 1.2 };
  const sectionDesc: React.CSSProperties = { fontSize: 15.5, color: pv.textMuted, margin: '0 0 18px', lineHeight: 1.65 };
  const panel: React.CSSProperties = {
    border: hair, borderRadius: pv.radiusLg, background: pv.surface, boxShadow: pv.shadowCard,
  };
  const codePillStyle: React.CSSProperties = {
    ...monoStyle, fontSize: 11.5, background: pv.surfaceMuted, color: onMuted, padding: '2px 8px', borderRadius: 6,
  };
  const sectionH3: React.CSSProperties = { fontSize: 21, fontWeight: 750, margin: '0 0 16px', letterSpacing: '-0.01em' };
  /** 권장·피하기 카드 — 색 헤더 + 항목 기호로 훑어보기 가능하게 */
  const ruleCard = (title: string, tone: string, mark: string, items: string[]): React.ReactNode => (
    <div style={{ border: hair, borderRadius: pv.radiusMd, background: pv.surface, overflow: 'hidden' }}>
      <div
        style={{
          display: 'flex', alignItems: 'center', gap: 8, padding: '11px 18px',
          background: withAlpha(tone, 0.09, pv.surfaceMuted), borderBottom: `1px solid ${withAlpha(tone, 0.22, pv.borderC)}`,
        }}
      >
        <span
          aria-hidden
          style={{
            width: 20, height: 20, borderRadius: '50%', background: tone, color: '#FFFFFF',
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 700,
          }}
        >
          {mark}
        </span>
        <span style={{ fontSize: 14, fontWeight: 700, color: tone }}>{title}</span>
      </div>
      <ul style={{ listStyle: 'none', margin: 0, padding: '14px 18px', display: 'grid', gap: 9 }}>
        {items.map((t) => (
          <li key={t} style={{ display: 'flex', gap: 9, alignItems: 'flex-start', fontSize: 14.5, lineHeight: 1.6 }}>
            <span aria-hidden style={{ color: tone, flex: 'none', marginTop: 1, fontSize: 12 }}>{mark}</span>
            <span>{t}</span>
          </li>
        ))}
      </ul>
    </div>
  );

  /** 섹션 제목 — 강조색 바를 달아 스크롤 중에도 구획이 눈에 걸리게 한다 */
  const secTitle = (text: string): React.ReactNode => (
    <h3 style={{ ...sectionH3, display: 'flex', alignItems: 'center', gap: 10 }}>
      <span aria-hidden style={{ width: 4, height: 19, borderRadius: 2, background: pv.primary, flex: 'none' }} />
      {text}
    </h3>
  );
  const propLabel: React.CSSProperties = {
    fontSize: 12, fontWeight: 700, color: pv.textMuted, letterSpacing: '0.08em',
    textTransform: 'uppercase', margin: '0 0 10px',
  };
  const specTable: React.CSSProperties = { width: '100%', borderCollapse: 'collapse', fontSize: 13.5, minWidth: 520 };
  const specTh: React.CSSProperties = {
    textAlign: 'left', padding: '11px 14px', borderBottom: `2px solid ${pv.borderC}`,
    fontSize: 11.5, fontWeight: 700, color: onMuted, whiteSpace: 'nowrap', letterSpacing: '0.06em',
    textTransform: 'uppercase', background: pv.surfaceMuted,
  };
  const specTd: React.CSSProperties = { padding: '12px 14px', borderBottom: hair, whiteSpace: 'nowrap' };

  /* ── 섹션 렌더러 ── */

  const renderIntro = () => {
    /* 설명이 길면 첫 문장만 리드로 두고 나머지는 접는다 — 개요가 벽글이면 안 읽힌다 */
    const fullDesc = (system.description ?? '').trim();
    const [leadDesc, restDesc] = (() => {
      if (fullDesc.length <= 160) return [fullDesc, ''];
      let head = '';
      for (const m of fullDesc.slice(0, 300).matchAll(/[\s\S]*?[.。!?](\s|$)/g)) {
        head = fullDesc.slice(0, m.index! + m[0].length).trim();
        if (head.length >= 60) break;
      }
      if (!head || head.length < 20) head = fullDesc.slice(0, 160).trim();
      return [head, fullDesc.slice(head.length).trim()];
    })();

    /* 히어로 — 브랜드 색 자체를 화면으로 쓴다. 이 페이지가 곧 그 디자인 시스템의 첫인상이다 */
    const heroA = pv.primary;
    /** 대표색의 실제 토큰 이름 — 별칭으로 뽑은 값과 featureColors 첫 항목이 다를 수 있다 */
    // 같은 값을 가진 토큰이 여럿이면(accent-normal · format-word · plan-smart 가 모두 #1d7ff9)
    // 대표성 순으로 정렬된 featureColors 를 먼저 본다 — 알파벳 첫 항목은 대표 이름이 아니다.
    const heroKey = featureColors.find(([, v]) => v === heroA)?.[0]
      ?? Object.entries(active.color ?? {}).find(([, v]) => v === heroA)?.[0]
      ?? 'primary';
    /* 두 번째 색은 색조가 **다른** 것으로 — 같은 계열끼리 이으면 그라디언트가 한 덩어리로 뭉갠다.
       단 보색까지 가면 튀므로 0.35 이내에서 가장 먼 색을 고른다. */
    const heroB = (() => {
      const base = toHsl(heroA)?.h;
      const cands = featureColors.filter(([, v]) => v !== heroA).map(([, v]) => v);
      if (cands.length === 0) return pv.primaryHover;
      if (base === undefined) return cands[0];
      const gap = (v: string) => {
        const h = toHsl(v)?.h;
        if (h === undefined) return 0;
        const d = Math.abs(h - base);
        return Math.min(d, 1 - d);
      };
      const scored = cands.map((v) => ({ v, d: gap(v) })).sort((a, b) => b.d - a.d);
      return (scored.find((x) => x.d <= 0.35) ?? scored[0]).v;
    })();
    const heroInk = readableOn(heroA) ?? '#FFFFFF';
    const heroDim = heroInk === '#FFFFFF' ? 'rgba(255,255,255,0.78)' : 'rgba(17,24,39,0.72)';
    /* 제목은 이 시스템의 디스플레이 서체로 — 설명하지 않고 보여 준다 */
    const displayRole = typoGroups.roles.find((r) => /^(display|hero|title|heading1|h1)/.test(r.role));
    const heroFont = displayRole?.props['font-family'] ?? typoFamilies[0];
    const bigSize = typoGroups.scales.find((sc) => sc.prop === 'font-size')?.entries[0]?.[1];

    const tile: React.CSSProperties = { ...panel, borderRadius: pv.radiusLg, overflow: 'hidden', display: 'flex', flexDirection: 'column' };
    const tileFoot: React.CSSProperties = { padding: '13px 16px 15px', borderTop: hair };
    const tileName: React.CSSProperties = { fontSize: 13.5, fontWeight: 700 };
    const tileMeta: React.CSSProperties = { ...monoStyle, fontSize: 11.5, color: pv.textMuted, marginTop: 3 };

    return (
    <div>
      {/* ── 히어로 밴드 ── */}
      <section
        style={{
          position: 'relative', overflow: 'hidden', borderRadius: pv.radiusLg,
          background: `radial-gradient(120% 140% at 88% 8%, ${heroB} 0%, transparent 58%), linear-gradient(135deg, ${heroA}, ${heroB})`,
          color: heroInk, padding: 'clamp(34px, 5vw, 58px) clamp(26px, 4vw, 48px)',
          marginBottom: 18,
        }}
      >
        <div style={{ ...monoStyle, fontSize: 12.5, color: heroDim, letterSpacing: '0.04em' }}>
          {system.name} · v{system.version}
        </div>
        <h1
          style={{
            fontSize: 'clamp(34px, 5.4vw, 62px)', fontWeight: 800, lineHeight: 1.04,
            letterSpacing: '-0.025em', margin: '14px 0 0', maxWidth: 900,
            ...(heroFont ? { fontFamily: `${heroFont}, ${pv.font}, system-ui, sans-serif` } : null),
          }}
        >
          {system.title}
        </h1>
        {leadDesc && (
          <p style={{ fontSize: 'clamp(15px, 1.5vw, 18px)', lineHeight: 1.7, color: heroDim, margin: '18px 0 0', maxWidth: 640 }}>
            {leadDesc}
          </p>
        )}
      </section>

      {restDesc && (
        <details style={{ margin: '0 0 22px' }}>
          <summary style={{ cursor: 'pointer', fontSize: 13.5, color: pv.textMuted }}>자세히 보기</summary>
          <p style={{ fontSize: 14.5, color: pv.textMuted, lineHeight: 1.8, margin: '10px 0 0', maxWidth: 780 }}>{restDesc}</p>
        </details>
      )}

      {/* ── 한눈에 — 색 / 서체 / 컴포넌트를 각각 큰 면으로 ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: 14, marginBottom: 18 }}>
        {/* 브랜드 컬러 — 대표색 한 면 + 나머지는 점으로 */}
        <button onClick={() => navigate('foundation-color')} style={{ ...tile, padding: 0, cursor: 'pointer', textAlign: 'left', color: 'inherit', fontFamily: 'inherit', border: hair }}>
          <div style={{ height: 132, background: heroA, display: 'flex', alignItems: 'flex-end', padding: 14, gap: 6 }}>
            {featureColors.slice(1, 5).map(([k, v]) => (
              <span key={k} title={`--color-${k} · ${v}`} style={{ width: 22, height: 22, borderRadius: '50%', background: v, border: `2px solid ${heroInk === '#FFFFFF' ? 'rgba(255,255,255,0.55)' : 'rgba(255,255,255,0.85)'}` }} />
            ))}
          </div>
          <div style={tileFoot}>
            <div style={tileName}>브랜드 컬러</div>
            <div style={tileMeta}>{heroKey} · {heroA}</div>
          </div>
        </button>

        {/* 서체 — 이 시스템 글꼴로 크게 */}
        <button onClick={() => navigate('foundation-typography')} style={{ ...tile, padding: 0, cursor: 'pointer', textAlign: 'left', color: 'inherit', fontFamily: 'inherit', border: hair }}>
          <div
            style={{
              height: 132, background: pv.surfaceMuted, display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: 58, fontWeight: 700, letterSpacing: '-0.02em', color: onMuted,
              ...(heroFont ? { fontFamily: `${heroFont}, ${pv.font}, system-ui, sans-serif` } : null),
            }}
          >
            Ag
          </div>
          <div style={tileFoot}>
            <div style={tileName}>서체</div>
            <div style={tileMeta}>
              {heroFont ? primaryFontName(heroFont) : '시스템 기본'}
              {bigSize ? ` · 최대 ${bigSize}` : displayRole?.props['font-size'] ? ` · 최대 ${displayRole.props['font-size']}` : ''}
            </div>
          </div>
        </button>

        {/* 컴포넌트 — 실제 토큰으로 그린 조각 */}
        <button
          onClick={() => navigate(components.length > 0 ? `component-${components[0].name}` : 'intro')}
          style={{ ...tile, padding: 0, cursor: 'pointer', textAlign: 'left', color: 'inherit', fontFamily: 'inherit', border: hair }}
        >
          <div style={{ height: 132, background: pv.surface, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 10 }}>
            <span style={{ background: heroA, color: onPrimary, padding: '9px 20px', borderRadius: pv.radiusSm, fontSize: 13.5, fontWeight: 700 }}>
              주요 액션
            </span>
            <span style={{ display: 'flex', gap: 6 }}>
              <span style={{ border: hair, color: pv.textMuted, padding: '5px 12px', borderRadius: pv.radiusSm, fontSize: 12 }}>보조</span>
              <span style={{ background: pv.surfaceMuted, color: onMuted, padding: '5px 12px', borderRadius: 999, fontSize: 11.5, fontWeight: 700 }}>뱃지</span>
            </span>
          </div>
          <div style={tileFoot}>
            <div style={tileName}>컴포넌트</div>
            <div style={tileMeta}>
              {components.length > 0 ? `완성 코드 ${components.length}개` : specEntries.length > 0 ? `스펙 ${specEntries.length}개` : '화면 목업'}
            </div>
          </div>
        </button>
      </div>

      {/* ── 이동 카드 ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 14 }}>
        {(
          [
            ['파운데이션', `토큰 ${Object.values(active).reduce((n, m) => n + Object.keys(m).length, 0)}개`, flatNav.find((n) => n.id.startsWith('foundation-'))?.id ?? 'intro'],
            [
              '컴포넌트',
              components.length > 0
                ? `완성 코드 ${components.length}개`
                : specEntries.length > 0 || componentDocs.length > 0
                  ? `스펙 ${specEntries.length} · 문서 ${componentDocs.length}`
                  : '완성 코드 0개',
              components.length > 0
                ? `component-${components[0].name}`
                : specRes && specAssign.unassigned.length > 0
                  ? 'resource-spec-components'
                  : componentDocs.length > 0
                    ? `resource-${componentDocs[0].name}`
                    : 'intro',
            ],
            ['리소스', `문서 ${pureResources.length}개 · 다운로드`, pureResources.length > 0 ? `resource-${pureResources[0].name}` : 'downloads'],
          ] as Array<[string, string, string]>
        ).map(([title, desc, target]) => (
          <button
            key={title}
            onClick={() => navigate(target)}
            style={{ ...panel, borderRadius: pv.radiusMd, padding: 18, textAlign: 'left', cursor: 'pointer', color: 'inherit', fontFamily: 'inherit' }}
          >
            <div style={{ fontSize: 15, fontWeight: 800 }}>{title}</div>
            <div style={{ fontSize: 12.5, color: pv.textMuted, marginTop: 4 }}>{desc} →</div>
          </button>
        ))}
      </div>
      {introOverviewSections.length > 0 && (
        <div style={{ marginTop: 44 }}>
          {introOverviewSections.map((sec) => (
            <section key={sec.id} id={`ov-${sec.id}`} style={{ marginBottom: 34, scrollMarginTop: 90 }}>
              <h2 style={h2Style}>{sec.title}</h2>
              <div style={{ ...panel, borderRadius: pv.radiusLg, padding: '6px 20px', marginTop: 12 }}>
                <Md>{sec.body}</Md>
              </div>
            </section>
          ))}
        </div>
      )}
    </div>
    );
  };

  const renderBrandLogo = () => {
    // 타일 배경은 각 테마의 실제 캔버스 토큰 — 별칭 체인 적용(canvas/background 네이밍 브랜드)
    const aliasFrom = (map: Record<string, string> | undefined, fb: string) => {
      for (const k of ['surface', 'background', 'bg', 'canvas']) {
        const v = map?.[k];
        if (v) return v;
      }
      return fb;
    };
    const lightSurface = aliasFrom(tokens.color, '#FFFFFF');
    const darkSurface = aliasFrom(themes.dark?.color, aliasFrom(tokens.color, '#0B1120'));
    return (
      <div>
        <div style={overline}>BRAND</div>
        <h2 style={h2Style}>로고</h2>
        <p style={sectionDesc}>이 가이드의 네비·푸터에 표시되는 브랜드 로고 — 테마별 맥락에서 확인하세요</p>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: 16 }}>
          {(
            // 다크 테마 토큰 없는 시스템은 다크 타일 미렌더 (admin 슬롯 정책과 동일 — 채울 수 없는 dead-end 방지)
            (hasDark
              ? [
                  ['라이트', logo?.light, lightSurface],
                  ['다크', logo?.dark, darkSurface],
                ]
              : [['로고', logo?.light, lightSurface]]) as Array<[string, string | undefined, string]>
          ).map(([label, src, bg]) => (
            <div key={label} style={{ ...panel, borderRadius: pv.radiusLg, overflow: 'hidden' }}>
              <div style={{ height: 140, background: bg, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                {src ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={src} alt={`${system.title} — ${label}`} style={{ maxHeight: 56, maxWidth: '70%', objectFit: 'contain' }} />
                ) : (
                  <span style={{ fontSize: 12.5, color: readableOn(bg) === '#FFFFFF' ? 'rgba(255,255,255,0.6)' : 'rgba(17,24,39,0.5)' }}>
                    미등록
                  </span>
                )}
              </div>
              <div style={{ padding: '10px 14px', fontSize: 12.5, color: pv.textMuted }}>{hasDark ? `${label} 테마` : label}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  const renderFoundationColor = () => (
    <div>
      <div style={overline}>FOUNDATION</div>
      <h2 style={h2Style}>색상</h2>
      <p style={sectionDesc}>
        {dark ? '다크' : '라이트'} 값 기준 · 역할별로 묶었어요 · 코드에서는 <code style={monoStyle}>var(--color-이름)</code> 으로 사용
      </p>
      {groupColors(active.color ?? {}).map((fam) => (
        <section key={fam.label} style={{ marginBottom: 34 }}>
          <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, margin: '0 0 4px' }}>
            <h3 style={{ fontSize: 16, fontWeight: 750, margin: 0 }}>{fam.label}</h3>
            <span style={{ ...monoStyle, fontSize: 12, color: pv.textMuted }}>{fam.entries.length}</span>
          </div>
          <p style={{ fontSize: 13, color: pv.textMuted, margin: '0 0 14px' }}>{fam.desc}</p>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(152px, 1fr))', gap: 12 }}>
            {fam.entries.map((sw) => (
              <div key={sw.key} style={{ border: hair, borderRadius: pv.radiusMd, overflow: 'hidden', background: pv.surface }}>
                {/* 스와치는 값 그대로 — 흰색·투명에 가까운 색도 경계선으로 형태가 남는다 */}
                <div style={{ height: 54, background: sw.value, borderBottom: hair }} />
                <div style={{ padding: '8px 10px' }}>
                  <div style={{ ...monoStyle, fontSize: 11.5, fontWeight: 600, wordBreak: 'break-all', lineHeight: 1.35 }}>{sw.key}</div>
                  <div style={{ ...monoStyle, fontSize: 11, color: pv.textMuted, marginTop: 2 }}>{sw.value}</div>
                  {COLOR_HINTS[sw.key] && <div style={{ fontSize: 11, color: pv.textMuted, marginTop: 3, lineHeight: 1.4 }}>{COLOR_HINTS[sw.key]}</div>}
                  {sw.states.length > 0 && (
                    // 상태 변형 — 독립 카드로 두면 벽이 되고, 값은 알아야 하므로 칩으로 접는다
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, marginTop: 7, paddingTop: 7, borderTop: hair }}>
                      {sw.states.map(([label, val]) => (
                        <span
                          key={label}
                          title={`--color-${sw.key}-${label} · ${val}`}
                          style={{
                            display: 'inline-flex', alignItems: 'center', gap: 4, padding: '2px 6px 2px 3px',
                            borderRadius: 999, background: pv.surfaceMuted, fontSize: 10, color: onMuted,
                          }}
                        >
                          <span style={{ width: 11, height: 11, borderRadius: '50%', background: val, border: hair, flex: 'none' }} />
                          {label}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </section>
      ))}
      {overviewFor('color')}
    </div>
  );

  const renderFoundationTypography = () => {
    const { roles, scales, loose } = typoGroups;
    const SCALE_LABEL: Record<string, string> = {
      'font-size': '크기', 'font-weight': '굵기', 'line-height': '행간',
      'letter-spacing': '자간', 'font-family': '글꼴', 'text-transform': '대소문자', 'font-style': '스타일',
    };
    /** 속성 스케일 한 줄의 스펙시먼 — 그 속성만 실제로 적용해 차이를 보인다 */
    const scaleStyle = (prop: string, value: string): React.CSSProperties => ({
      fontFamily: prop === 'font-family' ? `${value}, ${pv.font}` : pv.font,
      fontSize: prop === 'font-size' ? value : 16,
      fontWeight: (prop === 'font-weight' ? value : undefined) as React.CSSProperties['fontWeight'],
      lineHeight: prop === 'line-height' ? value : undefined,
      letterSpacing: prop === 'letter-spacing' ? value : undefined,
      textTransform: (prop === 'text-transform' ? value : undefined) as React.CSSProperties['textTransform'],
      fontStyle: (prop === 'font-style' ? value : undefined) as React.CSSProperties['fontStyle'],
    });
    /** 이 역할의 실제 스타일 — 스펙시먼에 그대로 먹인다 */
    const styleOf = (r: TypoRole): React.CSSProperties => ({
      // 지정 글꼴이 없는 환경에서 브라우저 기본(대개 세리프)으로 떨어지면 스펙시먼이 더 오해를
      // 부른다 — 가이드 본문 글꼴을 마지막 폴백으로 붙인다(적용 여부는 위 배지가 알린다)
      fontFamily: r.props['font-family'] ? `${r.props['font-family']}, ${pv.font}` : pv.font,
      fontSize: r.props['font-size'],
      fontWeight: r.props['font-weight'] as React.CSSProperties['fontWeight'],
      lineHeight: r.props['line-height'],
      letterSpacing: r.props['letter-spacing'],
      textTransform: r.props['text-transform'] as React.CSSProperties['textTransform'],
      fontStyle: r.props['font-style'] as React.CSSProperties['fontStyle'],
    });
    const metaChip: React.CSSProperties = {
      ...monoStyle, fontSize: 11, color: onMuted, background: pv.surfaceMuted,
      padding: '2px 7px', borderRadius: 6,
    };
    return (
      <div>
        <div style={overline}>FOUNDATION</div>
        <h2 style={h2Style}>타이포그래피</h2>
        <p style={sectionDesc}>
          {roles.length > 0
            ? '역할별 스펙시먼 — 작은 크기부터. 각 줄은 그 역할의 실제 값(크기·굵기·행간·자간)이 적용된 모습이에요'
            : '속성별 스케일 — 각 줄은 그 값만 적용해 차이를 비교할 수 있어요'}
        </p>

        {roles.length > 0 && (
        <div style={{ ...panel, borderRadius: pv.radiusLg, padding: 4 }}>
          {roles.map((r, i) => (
            <div key={r.role} style={{ padding: '18px 20px', borderTop: i === 0 ? 'none' : hair }}>
              <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, flexWrap: 'wrap', marginBottom: 10 }}>
                <code style={{ ...monoStyle, fontSize: 12, fontWeight: 700 }}>{r.role}</code>
                {TYPO_PROPS.filter((pr) => r.props[pr] && pr !== 'font-family').map((pr) => (
                  <span key={pr} style={metaChip}>{r.props[pr]}</span>
                ))}
                {r.props['font-family'] && (
                  <span style={{ ...metaChip, background: 'transparent', color: pv.textMuted, padding: '2px 0' }}>
                    {primaryFontName(r.props['font-family'])}
                  </span>
                )}
              </div>
              {/* 스펙시먼 — 넘치는 큰 글씨가 줄바꿈 없이 잘리지 않게 wrap 허용 */}
              <div style={{ ...styleOf(r), wordBreak: 'keep-all', overflowWrap: 'anywhere' }}>
                다람쥐 헌 쳇바퀴 Sphinx of black quartz 0123
              </div>
            </div>
          ))}
        </div>
        )}

        {/* 속성 스케일 — 역할이 아니라 속성이 앞에 오는 네이밍(size-h1·weight-body) */}
        {scales.map((sc) => (
          <section key={sc.prop} style={{ marginBottom: 26 }}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: 9, margin: '0 0 10px' }}>
              <h3 style={{ fontSize: 16, fontWeight: 750, margin: 0 }}>{SCALE_LABEL[sc.prop] ?? sc.prop}</h3>
              <code style={{ ...monoStyle, fontSize: 11.5, color: pv.textMuted }}>{sc.prop}</code>
            </div>
            <div style={{ ...panel, borderRadius: pv.radiusMd, padding: 4 }}>
              {sc.entries.map(([name, value], i) => (
                <div
                  key={name}
                  style={{
                    display: 'flex', alignItems: 'baseline', gap: 16, flexWrap: 'wrap',
                    padding: '12px 18px', borderTop: i === 0 ? 'none' : hair,
                  }}
                >
                  <code style={{ ...monoStyle, fontSize: 12, fontWeight: 700, minWidth: 130 }}>{name}</code>
                  <span style={{ ...metaChip, minWidth: 54, textAlign: 'center' }}>{value}</span>
                  <span style={{ ...scaleStyle(sc.prop, value), flex: 1, minWidth: 200, overflowWrap: 'anywhere' }}>
                    다람쥐 헌 쳇바퀴 Sphinx 0123
                  </span>
                </div>
              ))}
            </div>
          </section>
        ))}

        {/* 역할로 묶이지 않는 낱개 토큰(공용 font-family 등) */}
        {loose.length > 0 && (
          <div style={{ marginTop: 18 }}>
            <div style={propLabel}>기타 토큰</div>
            <div style={{ ...panel, borderRadius: pv.radiusMd, padding: '12px 18px' }}>
              {loose.map(([k, v]) => (
                <div key={k} style={{ display: 'flex', gap: 12, fontSize: 12.5, padding: '3px 0' }}>
                  <span style={{ ...monoStyle, fontWeight: 600 }}>--typography-{k}</span>
                  <span style={{ ...monoStyle, color: pv.textMuted }}>{v}</span>
                </div>
              ))}
            </div>
          </div>
        )}
        {overviewFor('typography')}
      </div>
    );
  };

  const renderFoundationSpacing = () => (
    <div>
      <div style={overline}>FOUNDATION</div>
      <h2 style={h2Style}>간격</h2>
      <p style={sectionDesc}>실제 크기의 막대</p>
      <div style={{ ...panel, padding: 22, display: 'flex', flexDirection: 'column', gap: 10 }}>
        {sortByScale(active.spacing ?? {}).map(([key, value]) => (
          <div key={key} style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <span style={{ ...monoStyle, fontSize: 12, minWidth: 140 }}>--spacing-{key}</span>
            <div style={{ height: 14, width: value, maxWidth: '60%', background: pv.primary, borderRadius: 4, opacity: 0.85 }} />
            <span style={{ ...monoStyle, fontSize: 11.5, color: pv.textMuted }}>{value}</span>
          </div>
        ))}
      </div>
      {overviewFor('spacing')}
    </div>
  );

  const renderFoundationRadius = () => (
    <div>
      <div style={overline}>FOUNDATION</div>
      <h2 style={h2Style}>라운드</h2>
      <p style={sectionDesc}>모서리 곡률</p>
      <div style={{ display: 'flex', gap: 18, flexWrap: 'wrap' }}>
        {sortByScale(active.radius ?? {}).map(([key, value]) => (
          <div key={key} style={{ textAlign: 'center' }}>
            <div style={{ width: 88, height: 88, background: pv.primary, opacity: 0.9, borderRadius: value, display: 'flex', alignItems: 'center', justifyContent: 'center', color: onPrimary, ...monoStyle, fontSize: 11.5 }}>
              {key}
            </div>
            <div style={{ ...monoStyle, fontSize: 11.5, color: pv.textMuted, marginTop: 6 }}>{value}</div>
          </div>
        ))}
      </div>
      {overviewFor('radius')}
    </div>
  );

  const renderFoundationShadow = () => (
    <div>
      <div style={overline}>FOUNDATION</div>
      <h2 style={h2Style}>그림자</h2>
      <div style={{ display: 'flex', gap: 22, flexWrap: 'wrap', padding: '14px 4px' }}>
        {sortByScale(active.shadow ?? {}).map(([key, value]) => (
          <div key={key} style={{ textAlign: 'center' }}>
            <div style={{ width: 136, height: 88, background: pv.surface, border: hair, borderRadius: pv.radiusMd, boxShadow: value }} />
            <div style={{ ...monoStyle, fontSize: 12, marginTop: 12 }}>--shadow-{key}</div>
          </div>
        ))}
      </div>
      {overviewFor('shadow')}
    </div>
  );

  const renderFoundationOther = (cat: string) => (
    <div>
      <div style={overline}>FOUNDATION</div>
      <h2 style={h2Style}>{cat}</h2>
      <div style={{ ...panel, padding: 20 }}>
        {sortByScale(active[cat] ?? {}).map(([key, value]) => (
          <div key={key} style={{ display: 'flex', gap: 14, fontSize: 12.5, padding: '4px 0' }}>
            <span style={{ ...monoStyle, fontWeight: 600 }}>--{cat}-{key}</span>
            <span style={{ ...monoStyle, color: pv.textMuted }}>{value}</span>
          </div>
        ))}
      </div>
      {overviewFor(cat)}
    </div>
  );

  /* ── 브랜드 컴포넌트 스펙 견본 — {token.ref} 해석 유틸 ── */
  const CAT_ALIAS: Record<string, string> = {
    colors: 'color', color: 'color', rounded: 'radius', radii: 'radius', radius: 'radius',
    shadows: 'shadow', shadow: 'shadow', spacing: 'spacing', typography: 'typography',
  };
  /** "{colors.primary}" → 실제 값. 미해결·비참조는 원문 그대로(transparent 등 리터럴 허용) */
  const resolveSpecValue = (v: string | undefined): string => {
    if (!v) return '';
    const m = v.match(/^\{([\w-]+)\.([\w.-]+)\}$/);
    if (!m) return isSafeSpecValue(v) ? v : ''; // 리터럴은 소비 지점 게이트 통과분만
    const cat = CAT_ALIAS[m[1]] ?? m[1];
    return active[cat]?.[m[2].replace(/\./g, '-')] ?? '';
  };
  /** "{typography.button}" → role 이름 (평탄화 키 button-font-size… 조회용) */
  const specTypoRole = (v: string | undefined): string | null => {
    const m = v?.match(/^\{typography\.([\w.-]+)\}$/);
    return m ? m[1].replace(/\./g, '-') : null;
  };
  /** role 타이포를 견본 스타일로 (fontSize 는 아키타입별 표시 클램프 — 실제값은 메타에) */
  const specTypoStyle = (role: string | null, maxPx = 24): { style: React.CSSProperties; realSize?: string } => {
    if (!role) return { style: {} };
    const t = (suffix: string) => active.typography?.[`${role}-${suffix}`];
    const style: React.CSSProperties = {};
    const realSize = t('font-size');
    const px = realSize ? parseSize(realSize) : null;
    if (px !== null && realSize) style.fontSize = Math.min(px, maxPx);
    if (t('font-weight')) style.fontWeight = t('font-weight') as React.CSSProperties['fontWeight'];
    if (t('letter-spacing')) style.letterSpacing = t('letter-spacing');
    if (t('text-transform')) style.textTransform = t('text-transform') as React.CSSProperties['textTransform'];
    if (t('font-family')) style.fontFamily = t('font-family');
    return { style, realSize: px !== null && px > 24 ? realSize : undefined };
  };


  /**
   * 상태 변형 엔트리(-hover 등, getdesign.md 원본은 backgroundColor 만 두는 관례)는
   * base 엔트리 스펙을 상속하고 자기 값만 오버라이드 — 파란 사각형 강등 방지.
   * base 정확명 우선, 없으면 'button-primary' → 'button-primary48' 류 프리픽스 폴백.
   */
  const inheritedProps = (e: SpecEntry): SpecEntry['props'] => {
    if (!SPEC_STATE_SUFFIX_RE.test(e.name)) return e.props;
    const baseName = e.name.replace(SPEC_STATE_SUFFIX_RE, '');
    const base =
      specEntries.find((x) => x.name === baseName) ??
      specEntries.find((x) => x.name !== e.name && !SPEC_STATE_SUFFIX_RE.test(x.name) && x.name.startsWith(baseName));
    return base ? { ...base.props, ...e.props } : e.props;
  };

  /**
   * 스펙 1건 → 아키타입 견본 렌더.
   * faceOverride = 이 견본이 놓일 면(specTile 이 대조 타일을 깔 때 그 색). 투명 배경 스펙의
   * 글자색이 읽히는지 판단하는 기준이 페이지 배경이 아니라 실제 면이어야 한다.
   */
  const renderSpecSample = (e: SpecEntry, faceOverride?: string): React.ReactNode => {
    const props = inheritedProps(e);
    const bg = resolveSpecValue(props.backgroundColor) || 'transparent';
    const fgRaw = resolveSpecValue(props.textColor);
    // 스펙의 글자색이 그 면 위에서 안 읽히면 가독색으로 교정 — 자료가 배경과 비슷한 색을
    // 지정한 경우(discord 요금제 카드 등) 견본에서 글자가 통째로 사라진다.
    const fgWanted = fgRaw || (bg !== 'transparent' ? readableOn(bg) ?? pv.text : pv.text);
    const fgFace = bg !== 'transparent' ? bg : faceOverride ?? pv.surface;
    const fgContrast = contrast(fgWanted, fgFace);
    const fg = fgContrast !== null && fgContrast < 2.2 ? (readableOn(fgFace) ?? pv.text) : fgWanted;
    const radius = resolveSpecValue(props.rounded) || resolveSpecValue(props.radius) || '0px';
    const arch = specArchetype(e.name);
    // 견본은 형태 표현이 목적 — 대형 스펙 패딩(80px 밴드 등)은 표시상 클램프 (실값은 메타 라벨)
    const clampPad = (v: string | undefined, max: number): string | undefined => {
      if (!v || v.includes('{') || !isSafeSpecValue(v)) return undefined;
      return v
        .split(/\s+/)
        .map((tk2) => {
          const n = parseSize(tk2);
          return n !== null && n > max ? `${max}px` : tk2;
        })
        .join(' ');
    };
    const padding = clampPad(props.padding, arch === 'band' || arch === 'card' ? 24 : 20);
    // height/width 소비 — 메타 라벨로만 두면 48/32/24 버튼이 전부 같은 높이로 렌더됨.
    // 표시상 클램프(실값은 메타 라벨), isSafeSpecValue 게이트 동일 적용
    const clampSize = (v: string | undefined, max: number): number | undefined => {
      if (!v || v.includes('{') || !isSafeSpecValue(v)) return undefined;
      const n = parseSize(v);
      return n === null ? undefined : Math.min(n, max);
    };
    // size: 48px 처럼 한 값으로 정사각을 지정하는 스펙이 흔하다 — 안 읽으면 아이콘 버튼이 카드로 그려진다
    const specSize = clampSize(props.size, 240);
    const specH = clampSize(props.height, 64) ?? (specSize !== undefined ? Math.min(specSize, 64) : undefined);
    const specW = clampSize(props.width, 240) ?? specSize;
    const role = specTypoRole(props.typography);
    const typoMax =
      arch === 'nav' || arch === 'tab' || arch === 'segment' || arch === 'toggle' || arch === 'checkbox' || arch === 'radio'
        ? 13
        : arch === 'badge' ? 12 : arch === 'button' ? 15 : arch === 'card' || arch === 'band' ? 18 : 20;
    const { style: typo, realSize } = specTypoStyle(role, typoMax);
    const isTransparent = bg === 'transparent' || bg === '';
    const border = isTransparent ? `1px solid ${fg}` : '1px solid transparent';

    // 계산 불가한 색 형식(그라디언트·키워드) 위 전면 채색 금지 원칙 — 피처 카드와 동일하게 강등
    if (!isTransparent && !fgRaw && readableOn(bg) === null) {
      return (
        <div
          style={{
            ...panel, background: pv.surfaceMuted, color: onMuted,
            borderRadius: pv.radiusMd, borderTop: `6px solid ${bg}`, padding: '14px 16px', fontSize: 12.5,
          }}
        >
          Aa 견본
        </div>
      );
    }

    // 선택 컨트롤은 이름 자체가 상태인 경우가 많다 (checkbox-default / -checked / -disabled)
    const en = e.name.toLowerCase();
    /*
     * 기본 상태 판정 — 이름에 off 단서가 있거나, **같은 이름 + -checked/-selected 엔트리가
     * 따로 있으면** 이쪽이 꺼진 상태다. 둘 다 켜진 모습으로 그리면 두 견본이 구분되지 않는다.
     */
    const hasOnTwin = ['-checked', '-selected', '-active', '-on'].some((sfx) =>
      specEntries.some((x) => x.name.toLowerCase() === `${en}${sfx}`),
    );
    const specOff = hasOnTwin || /(default|unchecked|off|inactive|idle|rest|미선택)/.test(en);
    const specDisabled = /disabled/.test(en);
    /** 컨트롤 옆 라벨 — 실제 화면처럼 보여야 사람이 크기·정렬을 가늠할 수 있다 */
    const ctlLabel = (text: string) => {
      // 대조 타일 위에 놓이면 페이지 글자색이 아니라 그 타일 기준으로 읽혀야 한다
      // (다크 시스템의 투명 체크박스가 흰 타일에 올라가면 밝은 라벨이 사라진다)
      const face = faceOverride ?? pv.surface;
      const base = specDisabled ? pv.textMuted : pv.text;
      const gap = contrast(solidOf(base), solidOf(face));
      const col = gap !== null && gap < 2.6 ? readableOn(solidOf(face)) ?? base : base;
      return <span style={{ fontSize: 13, color: col, fontFamily: 'inherit' }}>{text}</span>;
    };

    if (arch === 'toggle') {
      // ON/OFF 트랙 + 흰 썸 — width×height 스펙 그대로 (기본 52×30). 클릭으로 실제 전환
      return (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10 }}>
          <LiveToggle
            w={specW ?? 52}
            h={specH ?? 30}
            radius={radius !== '0px' ? radius : 999}
            onBg={isTransparent ? pv.primary : bg}
            offBg={pv.surfaceMuted}
            initialOn={!specOff}
            disabled={specDisabled}
          />
          {ctlLabel('알림 받기')}
        </span>
      );
    }
    if (arch === 'checkbox' || arch === 'radio') {
      const s2 = specH ?? specW ?? 20;
      const fill = isTransparent ? pv.primary : bg;
      return (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10 }}>
          <LiveCheck
            kind={arch}
            size={s2}
            fill={fill}
            radius={radius !== '0px' ? radius : 6}
            idleBorder={pv.borderC}
            markColor={readableOn(fill) ?? '#FFFFFF'}
            initialOn={!specOff}
            disabled={specDisabled}
          />
          {ctlLabel(arch === 'radio' ? '기본 배송지' : '약관에 동의합니다')}
        </span>
      );
    }
    if (arch === 'tab') {
      return (
        <LiveTabs
          accent={isTransparent ? pv.primary : bg}
          activeColor={fgRaw ?? pv.text}
          idleColor={pv.textMuted}
          typo={typo}
          hair={hair}
        />
      );
    }
    if (arch === 'segment') {
      const fill = isTransparent ? pv.primary : bg;
      return (
        <LiveSegment
          fill={fill}
          trackBg={pv.surfaceMuted}
          radius={radius !== '0px' ? radius : 999}
          height={specH}
          onFill={readableOn(fill) ?? '#FFFFFF'}
          idle={onMuted}
          typo={typo}
        />
      );
    }
    if (arch === 'button') {
      // 같은 이름 + '-hover' 엔트리가 있으면 실제 hover 색으로 전환 (없으면 미세 밝기 변화)
      const hoverEntry = specEntries.find((x) => x.name === `${e.name}-hover`);
      const hoverStyle = hoverEntry
        ? {
            ...(resolveSpecValue(hoverEntry.props.backgroundColor) ? { background: resolveSpecValue(hoverEntry.props.backgroundColor) } : null),
            ...(resolveSpecValue(hoverEntry.props.textColor) ? { color: resolveSpecValue(hoverEntry.props.textColor) } : null),
          }
        : undefined;
      // 정사각 스펙(width==height)은 아이콘 전용 버튼이다 — 라벨을 넣으면 글자가 세로로 쌓인다
      const iconOnly = specW !== undefined && specH !== undefined && Math.abs(specW - specH) <= 2;
      return (
        <LiveButton
          label={iconOnly ? '＋' : typo.textTransform === 'uppercase' ? 'DISCOVER' : '버튼 라벨'}
          hover={hoverStyle}
          base={{
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', boxSizing: 'border-box',
            background: isTransparent ? 'transparent' : bg, color: fg, borderRadius: radius,
            // height 스펙이 있으면 상하 패딩은 높이가 대신함 — 기본 패딩 폴백도 그에 맞춰 축소
            padding: iconOnly ? 0 : padding ?? (specH !== undefined ? '0 18px' : '12px 28px'),
            ...(specH !== undefined ? { height: specH } : null),
            ...(specW !== undefined ? { width: specW } : null),
            border,
            fontSize: iconOnly ? Math.max(13, Math.round((specH ?? 40) * 0.42)) : 14,
            fontWeight: 600,
            ...typo,
            ...(iconOnly ? { lineHeight: 1 } : null),
          }}
        />
      );
    }
    if (arch === 'input') {
      return (
        <LiveInput
          placeholder="입력해 보세요"
          style={{
            background: isTransparent ? 'transparent' : bg, color: fg, borderRadius: radius,
            padding: padding ?? '12px 16px', border: `1px solid ${pv.borderC}`, fontSize: 13.5,
            boxSizing: 'border-box', width: '100%',
            ...(specH !== undefined ? { height: specH, paddingTop: 0, paddingBottom: 0 } : null),
            ...typo,
          }}
        />
      );
    }
    if (arch === 'cell') {
      // 달력 날짜·아바타처럼 한 변이 같은 셀 — 스펙이 height 만 주므로 width 를 묶는다
      const side = specH ?? specW ?? 40;
      return (
        <span
          style={{
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', boxSizing: 'border-box',
            width: side, height: side, flex: 'none',
            background: isTransparent ? 'transparent' : bg, color: fg, borderRadius: radius, border,
            fontSize: Math.max(9, Math.round(side * 0.35)), fontWeight: 600, ...typo,
          }}
        >
          {side >= 20 ? '15' : null}
        </span>
      );
    }
    if (arch === 'badge') {
      return (
        <span style={{ display: 'inline-flex', alignItems: 'center', boxSizing: 'border-box', background: isTransparent ? 'transparent' : bg, color: fg, borderRadius: radius, padding: padding ?? '4px 12px', ...(specH !== undefined ? { height: specH } : null), border, fontSize: 11, fontWeight: 600, ...typo }}>
          {typo.textTransform === 'uppercase' ? 'NEW' : '뱃지'}
        </span>
      );
    }
    if (arch === 'nav') {
      return (
        <div style={{ background: isTransparent ? 'transparent' : bg, color: fg, borderRadius: radius, padding: padding ?? '12px 16px', display: 'flex', alignItems: 'center', gap: 14, border: `1px solid ${pv.borderC}`, minWidth: 0 }}>
          <strong style={{ fontSize: 13, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 120, ...typo }}>{system.title}</strong>
          <span style={{ fontSize: 12, opacity: 0.75, whiteSpace: 'nowrap', ...typo }}>메뉴</span>
          <span style={{ fontSize: 12, opacity: 0.75, whiteSpace: 'nowrap', ...typo }}>제품</span>
        </div>
      );
    }
    if (arch === 'card' || arch === 'band') {
      /*
       * 정사각 소형(carousel-arrow 48px 등)은 카드가 아니라 아이콘 버튼이다.
       * 이름이 아키타입에 안 걸려 card 로 떨어진 것뿐 — 제목·본문을 얹으면 정체가 왜곡된다.
       */
      if (specW !== undefined && specH !== undefined && Math.abs(specW - specH) <= 2 && specW <= 80) {
        return (
          <span
            style={{
              display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              width: specW, height: specW, borderRadius: radius, background: isTransparent ? 'transparent' : bg,
              color: fg, border: `1px solid ${pv.borderC}`, fontSize: Math.max(13, Math.round(specW * 0.34)), lineHeight: 1,
            }}
          >
            ›
          </span>
        );
      }
      /*
       * 카드는 이름이 곧 용도다(stat-card·step-card·auth-form-card…). 전부 '제목+본문'
       * 한 덩어리로 그리면 시스템이 달라도, 변형이 달라도 똑같아 보인다.
       * 이름 힌트로 골격만 갈라준다 — 값은 여전히 스펙에서만 온다.
       */
      const n = e.name.toLowerCase();
      const shape: 'media' | 'stat' | 'step' | 'rank' | 'form' | 'empty' | 'dialog' | 'plain' =
        /(empty|placeholder|blank|no-data)/.test(n) ? 'empty'
        : /(photo|image|thumb|pin|tile|media|cover|gallery)/.test(n) ? 'media'
        : /(stat|metric|number|count|score|rating)/.test(n) ? 'stat'
        : /(step|stage|process|phase)/.test(n) ? 'step'
        : /(rank|leaderboard|-row|list-item)/.test(n) ? 'rank'
        : /(auth|login|signup|sign-in|form|input)/.test(n) ? 'form'
        : /(modal|dialog|popup|sheet)/.test(n) ? 'dialog'
        : 'plain';
      const inner = padding && padding !== '0px' && padding !== '0' ? padding : '14px 16px';
      const accentA = isTransparent ? pv.primary : bg;
      const accentB = featureColors[1]?.[1] ?? pv.primaryHover;
      const onAccent = readableOn(pv.primary) ?? '#FFFFFF';
      const dim = { opacity: 0.72 };
      // 카드 면이 어두우면 안쪽 요소도 어두운 쪽으로 — 토큰(surfaceMuted)은 페이지 배경 기준이라 못 쓴다
      const faceDark = readableOn(solidOf(isTransparent ? pv.surface : bg)) !== '#111827';
      const wellBg = faceDark ? 'rgba(255,255,255,0.10)' : 'rgba(0,0,0,0.05)';
      const wellEdge = faceDark ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.12)';
      // 카드 테두리는 스펙 값이 있으면 그걸 쓴다 — 없을 때만 면 밝기로 추정
      const cardEdge = resolveSpecValue(props.borderColor) || wellEdge;
      const title = { fontSize: 14.5, fontWeight: 700, lineHeight: 1.35, ...typo } as React.CSSProperties;
      const sub = { fontSize: 12.5, marginTop: 5, lineHeight: 1.5, ...dim } as React.CSSProperties;
      const chip = (text: string) => (
        <span
          style={{
            display: 'inline-flex', padding: '6px 14px', borderRadius: pv.radiusSm,
            background: pv.primary, color: onAccent, fontSize: 12, fontWeight: 700,
          }}
        >
          {text}
        </span>
      );
      let body: React.ReactNode;
      if (shape === 'stat') {
        body = (
          <>
            <div style={{ fontSize: 11, letterSpacing: '0.08em', textTransform: 'uppercase', ...dim }}>지표 이름</div>
            <div style={{ fontSize: 30, fontWeight: 800, lineHeight: 1.1, marginTop: 4, ...typo }}>1,284</div>
            <div style={{ fontSize: 12, marginTop: 4, ...dim }}>지난주 대비 +12%</div>
          </>
        );
      } else if (shape === 'step') {
        body = (
          <div style={{ display: 'flex', gap: 10, alignItems: 'flex-start' }}>
            <span
              style={{
                flex: 'none', width: 24, height: 24, borderRadius: 999, background: pv.primary, color: onAccent,
                fontSize: 12, fontWeight: 700, display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
              }}
            >
              1
            </span>
            <div style={{ minWidth: 0 }}>
              <div style={title}>단계 제목</div>
              <div style={sub}>이 단계에서 할 일</div>
            </div>
          </div>
        );
      } else if (shape === 'rank') {
        body = (
          <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
            <span style={{ flex: 'none', fontSize: 13, fontWeight: 800, width: 16, ...dim }}>1</span>
            <span style={{ flex: 'none', width: 28, height: 28, borderRadius: 8, background: `linear-gradient(135deg, ${pv.primary}, ${accentB})` }} />
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ ...title, fontSize: 13.5 }}>항목 이름</div>
              <div style={{ ...sub, marginTop: 2, fontSize: 11.5 }}>보조 정보</div>
            </div>
          </div>
        );
      } else if (shape === 'form') {
        body = (
          <>
            <div style={title}>로그인</div>
            {['이메일', '비밀번호'].map((lb) => (
              <div key={lb} style={{ marginTop: 8 }}>
                <div style={{ fontSize: 11, marginBottom: 4, ...dim }}>{lb}</div>
                <div style={{ height: 30, borderRadius: pv.radiusSm, border: `1px solid ${wellEdge}`, background: wellBg }} />
              </div>
            ))}
            <div style={{ marginTop: 10 }}>{chip('계속하기')}</div>
          </>
        );
      } else if (shape === 'empty') {
        body = (
          <div style={{ textAlign: 'center', padding: '6px 0' }}>
            <div
              style={{
                width: 38, height: 38, borderRadius: 12, margin: '0 auto 10px',
                border: `1px dashed ${wellEdge}`, display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 16, ...dim,
              }}
            >
              ▢
            </div>
            <div style={{ ...title, fontSize: 13.5 }}>아직 항목이 없어요</div>
            <div style={{ ...sub, fontSize: 12 }}>첫 항목을 추가해 보세요</div>
          </div>
        );
      } else if (shape === 'dialog') {
        body = (
          <>
            <div style={title}>확인이 필요해요</div>
            <div style={sub}>이 작업을 진행할까요?</div>
            <div style={{ display: 'flex', gap: 8, marginTop: 12, justifyContent: 'flex-end' }}>
              <span style={{ padding: '6px 12px', borderRadius: pv.radiusSm, border: `1px solid ${wellEdge}`, fontSize: 12 }}>취소</span>
              {chip('확인')}
            </div>
          </>
        );
      } else {
        body = (
          <>
            <div style={title}>제목 텍스트</div>
            <div style={sub}>본문 한 줄 설명</div>
            {arch === 'band' && <div style={{ marginTop: 10 }}>{chip('자세히 보기')}</div>}
          </>
        );
      }
      return (
        <div
          style={{
            background: isTransparent ? 'transparent' : bg, color: fg, borderRadius: radius,
            border: `1px solid ${cardEdge}`, minWidth: shape === 'rank' ? 190 : 0, maxWidth: 240,
            overflow: 'hidden', wordBreak: 'keep-all', overflowWrap: 'anywhere',
          }}
        >
          {shape === 'media' && (
            <div aria-hidden style={{ height: 84, background: `linear-gradient(135deg, ${accentA === bg ? pv.primary : accentA}, ${accentB})`, opacity: 0.85 }} />
          )}
          <div style={{ padding: inner }}>{body}</div>
        </div>
      );
    }
    // 4px 스트라이프 같은 얇은 스펙에 'Aa 견본' 을 넣으면 글자가 그릇을 뚫는다 — 선으로 그린다
    if (specH !== undefined && specH < 20) {
      return (
        <div
          style={{
            height: specH, width: specW ?? 180, borderRadius: radius,
            background: isTransparent ? (fgRaw || pv.primary) : bg, boxSizing: 'border-box',
          }}
        />
      );
    }
    return (
      <div style={{ background: isTransparent ? pv.surfaceMuted : bg, color: isTransparent ? onMuted : fg, borderRadius: radius, padding: '14px 16px', fontSize: 12.5, border: `1px solid ${pv.borderC}`, boxSizing: 'border-box', ...(specH !== undefined ? { height: specH, display: 'flex', alignItems: 'center', paddingTop: 0, paddingBottom: 0 } : null), ...(specW !== undefined ? { width: specW } : null) }}>
        Aa 견본
      </div>
    );
  };

  /**
   * Properties 견본 타일 — 라이트 전용 변형(투명 배경 + 어두운 글자)을 다크 페이지에서 보면
   * 형태가 통째로 사라진다. 캔버스와 대비가 없을 때만 반대 톤 배경 위에 올려 준다.
   */
  const specTile = (e: SpecEntry): React.ReactNode => {
    const props = inheritedProps(e);
    const bg = resolveSpecValue(props.backgroundColor);
    const ink = resolveSpecValue(props.textColor) || resolveSpecValue(props.borderColor);
    const hasFace = Boolean(bg && bg !== 'transparent');
    const inkGap = ink ? contrast(ink, pv.surface) : null;
    // 면이 없는(투명) 변형만 대상 — 배경이 명시된 흐린 상태(disabled 등)는 그대로 둔다
    if (hasFace || inkGap === null || inkGap >= 2.2) return renderSpecSample(e);
    const tileBg = readableOn(ink) === '#111827' ? '#111827' : '#FFFFFF';
    return (
      <span style={{ display: 'inline-flex', padding: 10, borderRadius: pv.radiusSm, background: tileBg, border: hair }}>
        {renderSpecSample(e, tileBg)}
      </span>
    );
  };

  /**
   * 브랜드 스펙 조합 화면 — 업로드된 components: 스펙 엔트리만으로 화면을 조립 (AI·코드 실행 0).
   * 골격(배치)만 고정이고 모든 시각 조각은 renderSpecSample(실스펙 값). 어떤 엔트리가
   * 쓰였는지 카드마다 mono 라벨로 투명 표기. 상태 변형(-hover 등)은 조립에서 제외.
   */

  /**
   * 컴포넌트 문서 페이지 — PDS 문서 사이트 구성(Properties → Guidelines → Specification → 코드).
   * Properties·Specification 은 브랜드 스펙에서 결정적으로 파생하고(치수·색 표),
   * Guidelines 는 같은 이름의 컴포넌트 문서(산문)를 그대로 인라인한다.
   */
  const renderComponent = (c: GuideItem) => {
    const isGenerated = (c.usageMd ?? '').includes('자동 생성된 컴포넌트');
    const archEntries = specEntries.filter((e) => matchesComponent(e.name, c.name));
    const group = archEntries.length > 0 ? groupEntries(c.name as Archetype, archEntries) : null;
    /** 이 컴포넌트의 형태 — 미리보기·변형 렌더가 AI kind 보다 먼저 참조한다 */
    const compArch = specArchetype(c.name);
    /*
     * 스펙 엔트리가 전부 정사각이면 이 컴포넌트는 아이콘 전용이다(icon-button 40/32/28).
     * AI 는 preview.label 을 필수로 채우므로 '닫기' 같은 문구가 오는데, 그대로 그리면
     * 문서에 '레이블 없는 아이콘 버튼' 이라 써놓고 견본엔 글자가 나오는 모순이 생긴다.
     */
    const iconOnlyComp = archEntries.length > 0 && archEntries.every((e) => {
      const pr = inheritedProps(e);
      const sq = parseSize(pr.size ?? '');
      const w = parseSize(pr.width ?? '') ?? sq;
      const h = parseSize(pr.height ?? '') ?? sq;
      return w !== null && h !== null && Math.abs(w - h) <= 2;
    });

    /** 카드·밴드는 견본 높이가 제각각이라 wrap 정렬이 무너진다 — grid 로 행을 고정 */
    const boxy = compArch === 'card' || compArch === 'band';
    const gridForArch: React.CSSProperties = boxy
      ? { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', alignItems: 'stretch' }
      : {};
    const specCellStyle: React.CSSProperties = {
      display: 'flex', flexDirection: 'column', gap: 8, alignItems: 'flex-start',
      ...(boxy ? { justifyContent: 'space-between', height: '100%' } : null),
    };
    /** AI 구조화 문서 — usage 는 제목 바로 아래에 놓아야 읽기 흐름이 끊기지 않는다 */
    const docData = parseComponentDoc(c.usageMd);

    // 상태 엔트리는 base 유무와 무관하게 전부 노출 (button-disabled 처럼 base 없는 것 포함)
    const stateEntries = archEntries.filter((e) => SPEC_STATE_SUFFIX_RE.test(e.name));
    // 같은 컴포넌트를 설명하는 산문 문서(buttons ↔ button) — Guidelines 로 흡수
    // 아키타입 기준 매칭 — buttons→button, inputs-forms→input 처럼 이름이 정확히 같지 않아도 흡수
    const doc = resources.find(
      (r) => r.name !== 'spec-components' && (specArchetype(r.name) === c.name || r.name === c.name),
    );
    const specRow = (e: SpecEntry) => {
      const cells = SPEC_TABLE_COLS.map(([prop]) => e.props[prop] ?? '—');
      return { name: e.name, cells };
    };
    // 코드가 참조하는 토큰 변수 → 실제 값 (PDS 의 Token 표)
    const usedVars = [...new Set([...(c.code ?? '').matchAll(/var\(\s*(--[\w-]+)\s*\)/g)].map((m) => m[1]))].sort();
    const varValue = (v: string): string => {
      const m = v.match(/^--([a-z0-9]+)-(.+)$/);
      if (!m) return '—';
      return active[m[1]]?.[m[2]] ?? '—';
    };
    /*
     * 실물 렌더 — 호스트가 이 컴포넌트를 넘겨줬을 때만. 없으면 기존 골격(specTile).
     * props 는 스펙 이름에서 이미 파싱된 축을 그대로 쓴다 —
     * `button-primary48` → {variant:'primary', size:'48'}. 명명 규약이 곧 매핑이라
     * 별도 매트릭스 선언 없이 성립한다.
     */
    const Live = liveComponents?.[c.name] as
      | (React.ComponentType<Record<string, unknown>> & {
          supportedProps?: { acceptsChildren?: boolean; sampleLabel?: string } & Record<
            string,
            string[] | boolean | string | undefined
          >;
        })
      | undefined;
    /**
     * 컴포넌트가 지원한다고 알린 값만 실물로 그린다.
     * 스펙이 패키지보다 앞서 나가는 건 정상이고(변형이 먼저 정의되는 일),
     * 그때 모르는 값을 기본 얼굴로 그려 놓고 다른 이름표를 붙이면 거짓말이 된다.
     * 지원 목록을 안 알리는 컴포넌트는 전부 실물로 본다(구 버전 호환).
     */
    const liveSupports = (props: Record<string, unknown>): boolean => {
      const sup = Live?.supportedProps;
      if (!sup) return true;
      return Object.entries(props).every(([k, v]) => {
        const allowed = sup[k];
        if (!Array.isArray(allowed)) return true; // 값 목록이 아닌 플래그(acceptsChildren 등)
        // 양쪽 다 문자열로 맞춰 비교한다 — 스펙 이름에서 파싱한 축은 항상 문자열('48')인데
        // 컴포넌트는 숫자로 선언할 수 있다(Button.size: [24,32,…]). 한쪽만 String() 하면
        // 영영 불일치해 실물이 조용히 골격으로 떨어진다.
        return v === undefined || allowed.map(String).includes(String(v));
      });
    };
    const liveTile = (
      e: SpecEntry | undefined,
      props: Record<string, unknown>,
      label?: string,
    ): React.ReactNode => {
      if (!Live || !liveSupports(props)) return e ? specTile(e) : null;
      // void element 를 감싸는 컴포넌트(input 계열)에 라벨을 children 으로
      // 넘기면 React 가 던진다 — 컴포넌트가 스스로 받지 않는다고 선언한다.
      if (Live.supportedProps?.acceptsChildren === false) return <Live {...props} />;
      return (
        <Live {...props}>{label ?? Live.supportedProps?.sampleLabel ?? c.title}</Live>
      );
    };

    return (
      <div>
        <div style={overline}>COMPONENT</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          <h2 style={{ ...h2Style, margin: 0 }}>{c.title}</h2>
          <code style={codePillStyle}>{c.name}</code>
          {Live && (
            <span
              title="이 견본은 실제 컴포넌트 코드가 실행된 결과입니다"
              style={{
                fontSize: 11, fontWeight: 700, letterSpacing: '.02em', padding: '3px 8px',
                borderRadius: 999, background: pv.primary, color: onPrimary,
              }}
            >
              실물
            </span>
          )}
        </div>
        {c.description && <p style={{ ...sectionDesc, margin: '12px 0 0', maxWidth: 760 }}>{c.description}</p>}

        {/* 언제·왜 쓰는지 — 부제보다 긴 판단 기준. 화면을 보기 전에 읽는 자리다 */}
        {docData?.usage && (
          <p style={{ fontSize: 16, lineHeight: 1.8, color: pv.text, margin: '18px 0 0', maxWidth: 760 }}>{docData.usage}</p>
        )}

        {/* 이 컴포넌트만 문서가 비었을 때 — 목록에서 넘어온 사용자가 빈 화면을 오해하지 않게 */}
        {previewDraft && !docData && (
          <div
            style={{
              display: 'flex', alignItems: 'center', gap: 9, margin: '20px 0 0', padding: '11px 16px',
              borderRadius: pv.radiusMd, background: 'rgba(234,179,8,0.12)', border: '1px solid rgba(234,179,8,0.35)',
              fontSize: 13.5,
            }}
          >
            <span className="dgv-pulse" aria-hidden style={{ width: 8, height: 8, borderRadius: '50%', background: '#B45309', flex: 'none' }} />
            <span>설명·변형을 AI 가 채우는 중이에요. 잠시 후 새로고침하면 나타납니다.</span>
          </div>
        )}

        {/* 저장 경로는 참고 정보 — 본문 위계에서 내려 구분선 아래 메타 줄로 */}
        <div
          style={{
            display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap',
            margin: '24px 0 38px', paddingTop: 16, borderTop: hair, fontSize: 13, color: pv.textMuted,
          }}
        >
          {(() => {
            // 파일로 저장하는 컴포넌트와 패키지로 설치하는 컴포넌트는 들이는 방법이
            // 다르다 — 도구·스킬이 쓰는 판정(코드의 import)을 여기서도 그대로 쓴다.
            const d = componentDelivery(c);
            return d.mode === 'save' ? (
              <>
                <span style={{ fontWeight: 600 }}>저장 경로</span>
                <code style={codePillStyle}>{d.savePath}</code>
                <span>AI 는 이 코드를 수정 없이 그대로 사용합니다</span>
              </>
            ) : (
              <>
                <span style={{ fontWeight: 600 }}>설치</span>
                <code style={codePillStyle}>npm i {d.packages.join(' ')}</code>
                <span>패키지로 제공됩니다 — 위 코드는 사용 예제입니다</span>
              </>
            );
          })()}
        </div>

        {/* 실물은 등록됐는데 스펙에 축이 없는 컴포넌트(오버레이 계열이 흔하다) —
            아래 Properties 는 축에서 타일을 만들므로 통째로 생략된다. 그러면
            등록해 둔 실물이 어디에도 안 나오므로 견본 한 칸을 따로 둔다. */}
        {Live && !(group && (group.sizes.length > 0 || group.variants.length > 0)) && (
          <section style={{ marginBottom: 42 }}>
            {secTitle('Properties')}
            <div style={propLabel}>기본</div>
            <div style={{ ...panel, borderRadius: pv.radiusMd, padding: 20 }}>
              {liveTile(undefined, {})}
            </div>
          </section>
        )}

        {/* ── Properties — 크기 / 변형 / 상태 ── */}
        {/* 축이 하나뿐이고 아래 '변형' 섹션이 같은 내용을 더 풍부하게 보여주면 생략 (중복 회피) */}
        {group && (group.sizes.length > 0 || group.variants.length > 0)
          && !(group.sizes.length <= 1 && group.variants.length <= 1 && stateEntries.length === 0
               && (docData?.variants?.filter((v) => v.preview).length ?? 0) > 1) && (
          <section style={{ marginBottom: 42 }}>
            {secTitle('Properties')}
            {group.sizes.length > 1 && (
              <div style={{ marginBottom: 20 }}>
                <div style={propLabel}>Size</div>
                <div style={{ ...panel, borderRadius: pv.radiusMd, padding: 20, display: 'flex', flexWrap: 'wrap', gap: 20, alignItems: 'flex-end', ...gridForArch }}>
                  {group.sizes.map(([sz, e]) => (
                    <div key={sz} style={{ ...specCellStyle }}>
                      {liveTile(e, { size: sz, variant: group.variants[0]?.key })}
                      <span style={{ ...monoStyle, fontSize: 11, color: pv.textMuted }}>{sz}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            {group.variants.length > 0 && (
              <div style={{ marginBottom: 20 }}>
                <div style={propLabel}>{group.variants.length > 1 ? 'Variant' : '기본'}</div>
                <div style={{ ...panel, borderRadius: pv.radiusMd, padding: 20, display: 'flex', flexWrap: 'wrap', gap: 20, alignItems: 'flex-end', ...gridForArch }}>
                  {group.variants.map((v) => (
                    <div key={v.key} style={{ ...specCellStyle }}>
                      {liveTile(v.base, { variant: v.key, size: group.sizes.find(([sz]) => sz === '48')?.[0] ?? group.sizes[Math.floor(group.sizes.length / 2)]?.[0] })}
                      {group.variants.length > 1 && (
                        <span style={{ ...monoStyle, fontSize: 11, color: pv.textMuted }}>{v.key}</span>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}
            {stateEntries.length > 0 && (
              <div>
                <div style={propLabel}>State</div>
                <div style={{ ...panel, borderRadius: pv.radiusMd, padding: 20, display: 'flex', flexWrap: 'wrap', gap: 20, alignItems: 'flex-end', ...gridForArch }}>
                  {stateEntries.map((e) => (
                    <div key={e.name} style={{ ...specCellStyle }}>
                      {liveTile(e, {
                        variant: group.variants[0]?.key,
                        // hover 는 포인터 상태라 강제할 수 없다 — 골격으로 두고 나머지만 prop 으로
                        ...(/-disabled$/.test(e.name) ? { disabled: true } : null),
                      })}
                      <span style={{ ...monoStyle, fontSize: 11, color: pv.textMuted }}>
                        {e.name.match(SPEC_STATE_SUFFIX_RE)?.[1] ?? e.name}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </section>
        )}

        {/* ── Guidelines — 같은 컴포넌트의 규칙 산문 ── */}
        {/* ── Guidelines — AI 구조화 문서면 섹션별로, 아니면 산문 ── */}
        {(() => {
          const [usageMain, usageProv] = (c.usageMd ?? '').split(/\n---\n/);
          // 한 컴포넌트가 여러 문서에 걸쳐 설명되기도 한다(Band: 전용 문서 + Editorial Surfaces
          // 의 livery-band 문단). 1:1 문서만 쓰면 나머지 조각이 통째로 사라진다 — 합치되
          // 이미 담긴 조각은 걸러 중복을 막는다.
          const docPrimary = stripMarks(doc?.bodyMd ?? '');
          const docExtra = (docSplit.toComp.get(c.name) ?? []).filter((t) => !docPrimary.includes(t.slice(0, 40)));
          const docBody = [docPrimary, ...docExtra].filter(Boolean).join('\n\n');
          /*
           * usageMd 의 두 얼굴을 가른다.
           * - AI 구조화 문서(docData)가 있으면 본문은 이미 섹션별로 그려졌고, `---` 뒤만 출처다.
           * - 없으면 `---` 앞은 **사람이 `#### Usage` 에 쓴 사용 규칙**이다. 예전엔 이걸 통째로
           *   "생성 정보" 상자에 접어 넣었다 — 자동 생성 컴포넌트의 출처를 접으려던 분기가
           *   손으로 쓴 규칙까지 삼켰고, PDS 의 "Delete 는 되돌릴 수 없는 삭제에" 같은 판단
           *   근거가 접힌 채 아무도 못 봤다. 자동 생성 마커가 있는 것만 출처로 취급한다.
           */
          const provenance =
            stripMarks(usageProv ?? '') || (docData || !isGenerated ? '' : stripMarks(usageMain ?? ''));
          const humanUsage = docData || isGenerated ? '' : stripMarks(usageMain ?? '');

          /*
           * AI 문서가 그리는 그림(미리보기·변형)은 **실물 컴포넌트가 없는 시스템용 대역**이다.
           * 실물이 등록돼 있으면 위 Properties 가 이미 진짜를 그리므로, 대역까지 같이 내면
           * 같은 컴포넌트가 두 벌로 보이고 그중 하나(AI 그림)는 근사라 더 부실하다.
           * PDS 처럼 패키지가 붙은 시스템에서 "미리보기가 이상하다" 로 드러난 지점.
           */
          const hasLive = !!Live;

          // 변형 섹션(그림)과 '구성'의 변형 표는 같은 정보 — 하나만 나오게 조건을 공유한다
          const showVariantGallery =
            !hasLive
            && (docData?.variants?.filter((v) => v.preview).length ?? 0) > 1
            && !(group && group.variants.length > 1);

          const cell: React.CSSProperties = { ...specTd, whiteSpace: 'normal' };
          const listStyle: React.CSSProperties = { margin: 0, paddingLeft: 20, fontSize: 14.5, lineHeight: 1.85 };

          return (
            <>
              {docData && (
                <>
                  {/* 미리보기 — 스펙 스타일 + 명세 kind 로 우리가 그린다 (코드 실행 아님) */}
                  {docData.preview && !hasLive && !(group && (group.variants.length > 1 || group.sizes.length > 1)) && (
                    <section style={{ marginBottom: 42 }}>
                      {secTitle('미리보기')}
                      <div style={{ ...panel, borderRadius: pv.radiusMd, padding: 28, display: 'flex', justifyContent: 'center' }}>
                        {(() => {
                          const refOk = docData.preview?.styleRef
                            && specEntries.some((e) => e.name === docData.preview!.styleRef);
                          // 스펙 엔트리가 없으면 골격 기본색(강조색·캔버스)으로 떨어져 변형보다 부실해진다
                          const rep = refOk ? undefined : (docData.variants ?? []).find((v) => v.preview?.bg)?.preview;
                          return renderDocPreview(
                            docData.preview!,
                            compArch,
                            rep
                              ? {
                                  ...(docColor(rep.bg) ? { bg: docColor(rep.bg) } : {}),
                                  ...(docColor(rep.fg) ? { fg: docColor(rep.fg) } : {}),
                                  ...(docColor(rep.accent) ? { accent: docColor(rep.accent) } : {}),
                                  ...(docSize(rep.radius) ? { radius: docSize(rep.radius) } : {}),
                                }
                              : undefined,
                          );
                        })()}
                      </div>
                    </section>
                  )}

                  {/* 변형별 미리보기 — AI 가 지정한 토큰 색(실존 검증)으로 실제 모습 렌더.
                      스펙 기반 Properties 가 이미 변형을 보여주는 시스템에서는 생략(중복 회피). */}
                  {showVariantGallery && (
                    <section style={{ marginBottom: 42 }}>
                      {secTitle('변형')}
                      <div style={{ ...panel, borderRadius: pv.radiusMd, padding: 22, display: 'flex', flexWrap: 'wrap', gap: 22, alignItems: 'flex-start' }}>
                        {(docData.variants ?? []).map((v) => (
                          <div key={v.name} style={{ display: 'flex', flexDirection: 'column', gap: 8, alignItems: 'flex-start', minWidth: 170, maxWidth: 260 }}>
                            {/* 견본 높이가 변형마다 달라도(lg/sm) 라벨·설명은 같은 줄에서 시작하도록 */}
                            <div style={{ minHeight: 62, display: 'flex', alignItems: 'center' }}>
                            {(() => {
                              const node = renderVariantPreview(
                                docData.preview?.kind ?? 'button',
                                v.preview ?? {},
                                // 말풍선은 트리거 문구(label)가 아니라 안에 들어갈 내용(sub)이 본체다
                                iconOnlyComp
                                  ? '＋'
                                  : (docData.preview?.kind === 'bubble' ? docData.preview?.sub : undefined) ?? docData.preview?.label ?? v.name,
                                compArch,
                                v.name,
                                iconOnlyComp,
                              );
                              const kd = docData.preview?.kind ?? 'button';
                              return ARCH_SHAPED.has(compArch) || kd !== 'button' ? node : contrastTile(v.preview ?? {}, node);
                            })()}
                            </div>
                            <code style={codePillStyle}>{v.name}</code>
                            <span style={{ fontSize: 12, color: pv.textMuted, lineHeight: 1.5 }}>{v.desc}</span>
                          </div>
                        ))}
                      </div>
                    </section>
                  )}

                  {(docData.anatomy || docData.variants || docData.props) && (
                    <section style={{ marginBottom: 42 }}>
                      {secTitle('구성')}
                      <div style={{ display: 'grid', gap: 18, gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))' }}>
                        {docData.anatomy && (
                          <div>
                            <div style={propLabel}>Anatomy</div>
                            <ol style={{ listStyle: 'none', margin: 0, padding: 0, display: 'grid', gap: 10 }}>
                              {docData.anatomy.map((a, i) => (
                                <li key={a.part} style={{ display: 'flex', gap: 12, alignItems: 'flex-start' }}>
                                  <span
                                    aria-hidden
                                    style={{
                                      flex: 'none', width: 22, height: 22, borderRadius: '50%', marginTop: 1,
                                      display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
                                      background: pv.surfaceMuted, color: onMuted, fontSize: 11.5, fontWeight: 700,
                                    }}
                                  >
                                    {i + 1}
                                  </span>
                                  <span style={{ fontSize: 14.5, lineHeight: 1.65, maxWidth: 620 }}>
                                    <strong>{a.part}</strong>
                                    {a.detail ? <span style={{ color: pv.textMuted }}> — {a.detail}</span> : null}
                                  </span>
                                </li>
                              ))}
                            </ol>
                          </div>
                        )}
                        {docData.variants && !showVariantGallery && (
                          <div>
                            <div style={propLabel}>Variants</div>
                            <ul style={listStyle}>
                              {docData.variants.map((v) => (
                                <li key={v.name}>
                                  <code style={codePillStyle}>{v.name}</code>
                                  <span style={{ color: pv.textMuted }}> {v.desc}</span>
                                </li>
                              ))}
                            </ul>
                          </div>
                        )}
                      </div>
                      {docData.props && (
                        <div style={{ marginTop: 18, overflowX: 'auto' }}>
                          <div style={propLabel}>Props</div>
                          <table style={specTable}>
                            <thead>
                              <tr>
                                <th style={specTh}>이름</th>
                                <th style={specTh}>타입</th>
                                <th style={specTh}>설명</th>
                              </tr>
                            </thead>
                            <tbody>
                              {docData.props.map((pr) => (
                                <tr key={pr.name}>
                                  <td style={specTd}>
                                    <code style={{ ...monoStyle, fontSize: 12.5, fontWeight: 600, color: pv.text }}>{pr.name}</code>
                                  </td>
                                  <td style={specTd}>
                                    {pr.type
                                      ? <code style={{ ...codePillStyle, fontSize: 11.5 }}>{pr.type}</code>
                                      : <span style={{ color: pv.textMuted }}>—</span>}
                                  </td>
                                  <td style={{ ...cell, lineHeight: 1.6 }}>{pr.desc}</td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      )}
                    </section>
                  )}

                  {(docData.do || docData.dont) && (
                    <section style={{ marginBottom: 42 }}>
                      {secTitle('사용 규칙')}
                      <div style={{ display: 'grid', gap: 14, gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))' }}>
                        {docData.do && ruleCard('권장', pv.success, '✓', docData.do)}
                        {docData.dont && ruleCard('피하기', pv.danger, '✕', docData.dont)}
                      </div>
                    </section>
                  )}

                  {docData.a11y && (
                    <section style={{ marginBottom: 42 }}>
                      {secTitle('접근성')}
                      <div style={{ ...panel, borderRadius: pv.radiusMd, padding: '18px 22px' }}>
                        <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'grid', gap: 10 }}>
                          {docData.a11y.map((t) => (
                            <li key={t} style={{ display: 'flex', gap: 10, alignItems: 'flex-start', fontSize: 14.5, lineHeight: 1.6 }}>
                              <span aria-hidden style={{ color: pv.primary, flex: 'none', marginTop: 1 }}>◆</span>
                              <span>{t}</span>
                            </li>
                          ))}
                        </ul>
                      </div>
                    </section>
                  )}
                </>
              )}

              {/* 사람이 쓴 사용 규칙 — 펼쳐서 보인다. AI 구조화 문서의 '사용 규칙' 카드와 같은 자리 */}
              {humanUsage && (
                <section style={{ marginBottom: 42 }}>
                  {secTitle('사용 규칙')}
                  <div style={{ ...panel, borderRadius: pv.radiusMd, padding: '4px 18px' }}>
                    <Md>{humanUsage}</Md>
                  </div>
                </section>
              )}

              {/* `#### Variants` — props 표 등 변형 문서. 웹 도구·MCP 엔 [Variants] 로 이미 실리고
                  있었지만 가이드는 타입만 갖고 그리지 않았다(2026-08-27). 사람도 같은 표를 본다. */}
              {c.variantsMd && (
                <section style={{ marginBottom: 42 }}>
                  {secTitle('Props · Variants')}
                  <div style={{ ...panel, borderRadius: pv.radiusMd, padding: '4px 18px', overflowX: 'auto' }}>
                    <Md>{stripMarks(c.variantsMd)}</Md>
                  </div>
                </section>
              )}

              {/* 원문 문서·생성 정보는 접이식 — 사람이 읽는 정리본이 위에 오도록 */}
              {(docBody || provenance) && (
                <section style={{ marginBottom: 42 }}>
                  {docBody && (
                    <details style={{ marginBottom: 8 }}>
                      <summary style={{ cursor: 'pointer', fontSize: 13, color: pv.textMuted }}>
                        원문 가이드 (DESIGN.md 발췌)
                      </summary>
                      <div style={{ ...panel, borderRadius: pv.radiusMd, padding: '4px 18px', marginTop: 8 }}>
                        <Md>{docBody}</Md>
                      </div>
                    </details>
                  )}
                  {provenance && (
                    <details>
                      <summary style={{ cursor: 'pointer', fontSize: 12.5, color: pv.textMuted }}>생성 정보 (원본 스펙·변형 목록)</summary>
                      <div style={{ ...panel, borderRadius: pv.radiusMd, padding: '4px 18px', marginTop: 8 }}>
                        <Md>{provenance}</Md>
                      </div>
                    </details>
                  )}
                </section>
              )}
            </>
          );
        })()}

        {/* ── Specification — 치수 표 + 토큰 표 ──
             값 자체는 위 Properties 견본과 Anatomy 가 이미 보여 준다. 사람이 읽는 화면에서는
             표가 벽처럼 서 있어 흐름을 끊으므로 접어 두고, 실제 값을 대조할 때만 펼친다. */}
        {group && archEntries.length > 0 && (
          <section style={{ marginBottom: 42 }}>
            <details>
              <summary
                style={{
                  cursor: 'pointer', fontSize: 13.5, color: pv.textMuted,
                  padding: '10px 0', listStyle: 'revert',
                }}
              >
                Specification — 스펙 실측값{usedVars.length > 0 ? ` · 사용 토큰 ${usedVars.length}개` : ''}
              </summary>
              <div style={{ paddingTop: 14 }}>
            <div style={{ overflowX: 'auto', marginBottom: usedVars.length > 0 ? 20 : 0 }}>
              <table style={specTable}>
                <thead>
                  <tr>
                    <th style={specTh}>엔트리</th>
                    {SPEC_TABLE_COLS.map(([, label]) => (
                      <th key={label} style={specTh}>{label}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {archEntries.map(specRow).map((r) => (
                    <tr key={r.name}>
                      <td style={{ ...specTd, ...monoStyle, fontSize: 11.5 }}>{r.name}</td>
                      {r.cells.map((cell, i) => (
                        <td key={i} style={{ ...specTd, ...monoStyle, fontSize: 11.5, color: cell === '—' ? pv.textMuted : undefined }}>{cell}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {usedVars.length > 0 && (
              <div style={{ overflowX: 'auto' }}>
                <div style={propLabel}>사용 토큰</div>
                <table style={specTable}>
                  <thead>
                    <tr>
                      <th style={specTh}>CSS 변수</th>
                      <th style={specTh}>값</th>
                      <th style={specTh}>미리보기</th>
                    </tr>
                  </thead>
                  <tbody>
                    {usedVars.map((v) => {
                      const val = varValue(v);
                      const isColor = /^#|^rgb/.test(val);
                      return (
                        <tr key={v}>
                          <td style={{ ...specTd, ...monoStyle, fontSize: 11.5 }}>{v}</td>
                          <td style={{ ...specTd, ...monoStyle, fontSize: 11.5 }}>{val}</td>
                          <td style={specTd}>
                            {isColor ? (
                              <span style={{ display: 'inline-block', width: 34, height: 16, borderRadius: 4, background: val, border: hair }} />
                            ) : (
                              <span style={{ fontSize: 11.5, color: pv.textMuted }}>—</span>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
              </div>
            </details>
          </section>
        )}

        {/* ── 코드 ── */}
        {c.code && (
          <section>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, margin: '0 0 8px' }}>
              <h3 style={{ ...sectionH3, margin: 0 }}>코드</h3>
              <CopyButton text={c.code} label="코드 복사" border={hair} />
            </div>
            <pre style={{ ...monoStyle, margin: 0, padding: 20, fontSize: 12.5, lineHeight: 1.6, overflow: 'auto', maxHeight: 520, borderRadius: pv.radiusMd, background: 'rgba(15,23,42,0.88)', color: '#E2E8F0' }}>
              {c.code}
            </pre>
            <p style={{ fontSize: 12, color: pv.textMuted, marginTop: 8 }}>
              {isGenerated
                ? '위 Properties 미리보기가 이 코드의 동작입니다 — 코드 문자열 자체는 실행하지 않습니다(가이드 보안 불변식).'
                : '관리자가 작성한 코드는 보안상 실행하지 않고 표시만 합니다 — 프로젝트에 저장하면 그대로 동작합니다.'}
            </p>
          </section>
        )}
      </div>
    );
  };

  const renderResource = (r: GuideItem) => (
    <div>
      <div style={overline}>RESOURCE</div>
      <h2 style={h2Style}>{r.title}</h2>
      <div style={{ ...panel, borderRadius: pv.radiusLg, padding: '6px 20px', marginTop: 14 }}>
        <Md>{r.bodyMd ?? ''}</Md>
      </div>
    </div>
  );

  /** 스펙 엔트리 그리드 — 브랜드 스펙 페이지·컴포넌트 문서 상단 견본 공용 */
  /**
   * AI 문서의 preview 명세 → 미리보기 렌더. 마크업 골격은 우리가 고정하고(kind 화이트리스트)
   * 색·라운드는 참조 스펙 엔트리의 검증된 값만 입힌다 — 코드 실행이 아니다.
   */
  /** 변형 미리보기 — 색만 다른 같은 형태 (AI 가 지정한 토큰 var 이름은 검증 완료 상태) */
  /**
   * AI 문서의 색 표기 → 실제 CSS 값. 가이드에는 --color-* 변수가 선언돼 있지 않으므로
   * 토큰 맵에서 값을 꺼내야 한다 (검증을 통과한 원색 리터럴은 그대로).
   */
  const docColor = (v?: string): string | undefined => {
    if (!v) return undefined;
    if (v === 'transparent') return 'transparent';
    if (/^(#[0-9a-fA-F]{3,8}|rgba?\([0-9.,%\s]+\))$/.test(v)) return v;
    const m = v.match(/^--([a-z0-9]+)-(.+)$/);
    return m ? active[m[1]]?.[m[2]] : undefined;
  };

  /** AI 문서의 치수 표기 → 실제 CSS 값 (토큰 이름이면 조회, 리터럴은 그대로) */
  const docSize = (v?: string): string | undefined => {
    if (!v) return undefined;
    if (!v.startsWith('--')) return v;
    const m = v.match(/^--([a-z0-9]+)-(.+)$/);
    return m ? active[m[1]]?.[m[2]] : undefined;
  };

  const renderVariantPreview = (
    kind: string,
    colorsIn: { bg?: string; fg?: string; border?: string; accent?: string; height?: string; padding?: string; radius?: string; fontSize?: string },
    label: string,
    /** 컴포넌트 아키타입 — 체크박스를 막대로 그리지 않도록 AI 가 고른 kind 보다 우선한다 */
    arch?: Archetype,
    /** 변형 이름 — checked/disabled 처럼 이름 자체가 상태인 경우 초기값 판정 */
    variantName?: string,
    /** 아이콘 전용 컴포넌트 — 라벨 대신 기호를 넣고 정사각으로 그린다 */
    iconOnly?: boolean,
  ): React.ReactNode => {
    // 가이드 문서에는 --color-* CSS 변수가 선언돼 있지 않다 (토큰은 인라인 값으로 주입).
    // var() 를 그대로 쓰면 미정의라 무효 → 토큰 맵에서 **실제 값**으로 해석한다.
    let colors = colorsIn;
    const toVal = docColor;
    // 알약·원형 모서리(999px 등)는 버튼·칩에서만 의미가 있다. 표·목록·카드 골격에 그대로 주면
    // 컨테이너가 타원으로 뭉개진다 — 진입점에서 한 번만 정규화한다.
    const rawR = colors.radius && !colors.radius.startsWith('--')
      ? colors.radius
      : (colors.radius ? docSize(colors.radius) : undefined);
    const rPx = rawR ? parseSize(rawR) : null;
    const pillShape = kind === 'button' || kind === 'chip' || arch === 'badge' || arch === 'toggle'
      || arch === 'checkbox' || arch === 'radio' || arch === 'segment';
    // 50% 같은 백분율은 픽셀 파싱에 안 걸린다 — 별도로 잡지 않으면 표·목록이 타원이 된다
    const overRound = rawR ? (rawR.includes('%') || (rPx !== null && rPx > 24)) : false;
    if (overRound && !pillShape) colors = { ...colors, radius: '24px' };
    // 50% 는 정사각일 때만 원이 된다 — 우리 견본은 글자 폭에 맞춰 늘어나므로 알약으로 바꿔야
    // 라벨이 길 때 찌그러진 타원이 되지 않는다.
    else if (rawR?.includes('%')) colors = { ...colors, radius: '999px' };
    // 높이도 마찬가지 — 목록 한 줄에 100px 이 들어오면 형태가 무너진다
    const hPx = colors.height ? parseSize(docSize(colors.height) ?? colors.height) : null;
    if (!pillShape && hPx !== null && hPx > 64) colors = { ...colors, height: '64px' };
    const bg = toVal(colors.bg) ?? pv.surfaceMuted;
    /*
     * AI 가 배경·글자 토큰을 짝이 안 맞게 고르는 일이 있다(실측: avatar32 에
     * bg=fill-strong(#e8ebed) + fg=static-white → 대비 1.20, 글자가 사라짐).
     * 값을 존중하되 읽을 수 없는 조합만 글자색을 뒤집는다.
     */
    const fgRaw = toVal(colors.fg) ?? pv.text;
    const fgGap = bg === 'transparent' ? null : contrast(solidOf(fgRaw), solidOf(bg));
    const fg = fgGap !== null && fgGap < 2.2 ? (readableOn(solidOf(bg)) ?? fgRaw) : fgRaw;
    const border = toVal(colors.border);
    // 치수도 반영 — 같은 변형 그룹에서 크기 차이(standard/compact 등)가 보이게
    const sizeVal = (v?: string): string | undefined => {
      if (!v) return undefined;
      if (!v.startsWith('--')) return /^[\d.\s%pxrem-]+$/.test(v) ? (/^[\d.]+$/.test(v) ? `${v}px` : v) : undefined;
      const m = v.match(/^--([a-z0-9]+)-(.+)$/);
      return m ? active[m[1]]?.[m[2]] : undefined;
    };
    // 높이를 그대로 먹여도 되는 형태(한 줄짜리)와, 내용이 높이를 정해야 하는 형태를 가른다
    const oneLineShape = kind === 'button' || kind === 'chip' || kind === 'field' || kind === 'menu' || kind === 'row';
    const shell: React.CSSProperties = {
      background: bg,
      color: fg,
      // 면도 테두리도 없으면 글자만 떠 있어 컴포넌트로 안 보인다 — 최소 경계선을 준다
      border: border ? `1px solid ${border}` : bg === 'transparent' ? hair : '1px solid transparent',
      borderRadius: sizeVal(colors.radius) ?? pv.radiusMd,
      fontFamily: 'inherit',
      boxSizing: 'border-box',
      ...(oneLineShape && sizeVal(colors.height) ? { height: sizeVal(colors.height) } : {}),
      ...(sizeVal(colors.fontSize) ? { fontSize: sizeVal(colors.fontSize) } : {}),
    };
    const pad = sizeVal(colors.padding);

    /* ── 아키타입 우선 ──
     * AI 가 고르는 preview.kind 는 9종(button·card·bar…)뿐이라 체크박스·토글·탭처럼
     * 목록에 없는 형태는 전부 버튼으로 폴백돼 "파란 막대" 가 된다. 컴포넌트 이름에서
     * 판정한 아키타입이 명확하면 그 골격을 먼저 쓰고, 변형 색만 얹는다. */
    const vn = (variantName ?? '').toLowerCase();
    const isOff = /(^|[-_ ])(default|unchecked|off|inactive|empty|idle|rest)([-_ ]|$)/.test(vn);
    const isDisabled = /(disabled|비활성)/.test(vn);
    // 채움색이 캔버스와 사실상 같으면(미선택 상태 스펙을 대표로 잡은 경우) 강조색으로 —
    // 그대로 두면 체크박스·토글이 흰 바탕에 흰 면으로 그려져 형태가 안 보인다.
    const bgUsable = colors.bg && bg !== 'transparent' && (contrast(bg, pv.surface) ?? 0) >= 1.12;
    const accent = bgUsable ? bg : pv.primary;
    /** 변형이 명시한 강조색 — 인디케이터·선택 항목처럼 '면' 과 다른 역할 */
    const accentCol = toVal(colors.accent);
    /** 면 위에 얹는 글자색 — 대비가 모자라면 자동 교정 (회색 위 회색으로 글자가 사라지는 것 방지) */
    const inkOn = (ink: string | undefined, face: string): string => {
      if (ink) {
        const c = contrast(ink, face);
        if (c === null || c >= 2.5) return ink;
      }
      return readableOn(face) ?? pv.text;
    };
    const labelStyle: React.CSSProperties = { fontSize: 13, color: isDisabled ? pv.textMuted : pv.text, fontFamily: 'inherit' };

    if (arch === 'checkbox' || arch === 'radio') {
      const boxSize = parseSize(sizeVal(colors.height) ?? '') ?? 20;
      return (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10 }}>
          <LiveCheck
            kind={arch}
            size={Math.min(28, Math.max(14, boxSize))}
            fill={accent}
            radius={sizeVal(colors.radius) ?? 4}
            idleBorder={border ?? pv.borderC}
            markColor={inkOn(colors.fg ? fg : undefined, accent)}
            initialOn={!isOff}
            disabled={isDisabled}
          />
          <span style={labelStyle}>{label}</span>
        </span>
      );
    }
    if (arch === 'toggle') {
      const th = parseSize(sizeVal(colors.height) ?? '') ?? 24;
      return (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 10 }}>
          <LiveToggle
            w={Math.round(th * 1.8)}
            h={th}
            radius={sizeVal(colors.radius) ?? 999}
            onBg={accentCol ?? accent}
            offBg={border ?? pv.borderC}
            initialOn={!isOff}
            disabled={isDisabled}
          />
          <span style={labelStyle}>{label}</span>
        </span>
      );
    }
    if (arch === 'tab') {
      const bar = accentCol ?? accent;
      return <LiveTabs accent={bar} activeColor={inkOn(colors.fg ? fg : bar, pv.surface)} idleColor={pv.textMuted} typo={{}} hair={hair} />;
    }
    if (arch === 'segment') {
      // bg 는 트랙(컨테이너) 배경이고 선택 항목은 accent 다. 뒤바꾸면 선택 항목이 연회색으로
      // 칠해지고 그 위 회색 글자가 사라진다. 테두리 색을 배경으로 쓰는 것도 금물.
      const track = colors.bg ? bg : pv.surfaceMuted;
      /** 변형이 선택 색을 직접 지정했는지 — 지정했으면 그 색을 존중한다 */
      const fillGiven = Boolean(accentCol);
      let fill = accentCol ?? (colors.bg ? pv.primary : accent);
      /*
       * AI preview 명세에는 층이 하나뿐(bg·fg·border)이라 'filled' 처럼 선택 항목 색을
       * bg 로 적어 보내는 경우가 있다. 그대로 그리면 트랙과 선택 알약이 같은 색이 돼
       * 선택 표시가 사라진다 — 두 색이 붙어 있으면 알약을 대비되는 쪽으로 돌린다.
       */
      const fillGap = contrast(solidOf(fill), solidOf(track));
      const fillFlat = fillGap !== null && fillGap < 1.35;
      // 지정 색이 트랙과 붙어 있으면 그림자로 분리하고, 폴백 색이 겹친 경우만 색을 바꾼다
      if (fillFlat && !fillGiven) fill = readableOn(solidOf(track)) ?? fill;
      return (
        <span style={isDisabled ? { opacity: 0.5, display: 'inline-flex' } : undefined}>
        <LiveSegment
          fill={fill}
          trackBg={track}
          trackEdge={border}
          radius={sizeVal(colors.radius) ?? 999}
          height={parseSize(sizeVal(colors.height) ?? '') ?? undefined}
          onFill={inkOn(undefined, fill)}
          idle={inkOn(colors.fg ? fg : pv.textMuted, track)}
          typo={{}}
          elevate={fillFlat && fillGiven}
        />
        </span>
      );
    }
    if (arch === 'input') {
      return (
        <LiveInput
          placeholder={label}
          style={{ width: 200, padding: pad ?? '10px 12px', fontSize: 13, ...shell, background: colors.bg ? bg : pv.surface, color: colors.fg ? fg : pv.text, border: `1px solid ${border ?? pv.borderC}` }}
        />
      );
    }
    if (arch === 'cell') {
      const side = parseSize(sizeVal(colors.height) ?? '') ?? 40;
      return (
        <span
          style={{
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', flex: 'none',
            width: side, height: side, fontSize: Math.max(9, Math.round(side * 0.35)), fontWeight: 600,
            ...shell, borderRadius: sizeVal(colors.radius) ?? '50%',
          }}
        >
          {side >= 20 ? '15' : null}
        </span>
      );
    }
    if (arch === 'badge') {
      return <span style={{ display: 'inline-flex', alignItems: 'center', padding: pad ?? '4px 10px', fontSize: 11.5, fontWeight: 700, ...shell, borderRadius: sizeVal(colors.radius) ?? 999 }}>{label}</span>;
    }

    if (kind === 'chip') {
      return <span style={{ display: 'inline-flex', alignItems: 'center', padding: pad ?? '4px 12px', fontSize: 12, fontWeight: 600, ...shell, borderRadius: shell.borderRadius ?? 999 }}>{label}</span>;
    }
    if (kind === 'field') {
      return <div style={{ width: 190, padding: pad ?? '10px 12px', fontSize: 12.5, opacity: 0.9, display: 'flex', alignItems: 'center', ...shell }}>{label}</div>;
    }
    // 말풍선은 변형에서 **펼친 상태**로 — 호버 트리거만 보이면 변형 간 차이를 볼 수 없다
    if (kind === 'bubble') {
      return (
        <span style={{ display: 'inline-flex', maxWidth: 190, padding: pad ?? '7px 10px', fontSize: 12, lineHeight: 1.5, ...shell, borderRadius: sizeVal(colors.radius) ?? pv.radiusSm }}>
          {label}
        </span>
      );
    }
    // 목록형 골격은 변형에서 **항목 하나**로 축약 — 변형마다 목록 전체를 그리면 차이가 묻힌다
    if (kind === 'menu' || kind === 'row') {
      return (
        <div style={{ width: 190, padding: pad ?? '9px 12px', fontSize: 13, display: 'flex', alignItems: 'center', ...shell, borderRadius: sizeVal(colors.radius) ?? pv.radiusSm }}>
          {label}
        </div>
      );
    }
    // bar·bubble·row·menu 등 나머지 골격은 renderDocPreview 가 전부 갖고 있다 — 색만 덮어 재사용.
    // 여기서 폴백시키면 표·토스트 변형이 전부 빈 버튼 상자로 그려진다.
    if (kind !== 'button') {
      /** 큰 골격인데 변형 높이가 버튼급이면, 그 변형은 컴포넌트가 아니라 내부 부품을 말한다 */
      const vH = colors.height ? parseSize(sizeVal(colors.height) ?? '') : null;
      const partScoped = (kind === 'panel' || kind === 'card') && vH !== null && vH <= 56;
      return renderDocPreview(
        // 변형 그리드는 칸이 좁다 — 골격 기본 폭(토스트 등)이 칸을 넘어 겹치지 않게 좁혀 그린다
        { kind, label, width: kind === 'panel' || kind === 'card' ? 220 : 190 },
        undefined,
        {
          ...(/(single|one)[-_ ]?(button|btn)/.test(vn) ? { buttons: 1 as const } : {}),
          /*
           * 팝업·카드의 변형이 실제로는 '안에 든 버튼'을 가리키는 경우가 있다
           * (popup 의 primary/secondary/danger — height 48px 는 버튼 치수다).
           * 그대로 배경에 칠하면 확인 팝업 전체가 빨개진다. 강조 요소에만 준다.
           */
          ...(partScoped
            ? { accent: bg, accentFg: colors.fg ? fg : undefined }
            : {
                ...(colors.bg ? { bg } : {}),
                // fg 는 bg 와 짝일 때만 — 배경이 골격 기본값으로 남은 채 글자색만 바뀌면 대비가 깨진다
                ...(colors.bg && colors.fg ? { fg } : {}),
              }),
          ...(toVal(colors.accent) ? { accent: toVal(colors.accent) } : {}),
          // 테두리 색이 변형을 가르는 경우가 있다(bronze/silver/gold 티어 카드)
          ...(border ? { border } : {}),
          ...(sizeVal(colors.radius) ? { radius: sizeVal(colors.radius) } : {}),
        },
      );
    }
    // button 기본 — hover/press 동작 포함
    return (
      <LivePreviewButton
        label={label}
        base={{
          display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
          padding: pad ?? '10px 20px', fontSize: 13.5, fontWeight: 700, ...shell,
          // 아이콘 버튼은 정사각이다 — 변형 명세에 height 만 오므로 width 를 맞춰 준다
          ...(iconOnly && shell.height ? { width: shell.height, padding: 0, fontSize: 15, lineHeight: 1 } : null),
        }}
      />
    );
  };

  /**
   * 견본 타일 — 변형 색이 현재 캔버스와 대비가 없으면(라이트 전용 변형을 다크 페이지에서 보는 등)
   * 반대 톤 배경 위에 올려 형태가 사라지지 않게 한다.
   */
  const contrastTile = (colors: { bg?: string; fg?: string; border?: string }, node: React.ReactNode): React.ReactNode => {
    const val = (v?: string): string | undefined => {
      if (!v || v === 'transparent') return undefined;
      const m = v.match(/^--([a-z0-9]+)-(.+)$/);
      return m ? active[m[1]]?.[m[2]] : v;
    };
    const ink = val(colors.fg) ?? val(colors.border);
    const face = val(colors.bg);
    const inkGap = ink ? contrast(ink, pv.surface) : null;
    // 면이 없는(투명) 변형만 대상 — 배경이 명시된 흐린 상태(disabled 등)는 그대로 둔다
    if (face || inkGap === null || inkGap >= 2.2) return node;
    const tileBg = readableOn(ink ?? pv.text) === '#111827' ? '#111827' : '#FFFFFF';
    return (
      <span style={{ display: 'inline-flex', padding: 10, borderRadius: pv.radiusSm, background: tileBg, border: hair }}>
        {node}
      </span>
    );
  };

  const renderDocPreview = (
    spec: { kind: string; label?: string; sub?: string; icon?: string | null; width?: number; styleRef?: string },
    arch?: Archetype,
    /** 변형별 색·모서리 — 주어지면 스펙 값 대신 이걸 쓴다 (변형 섹션이 같은 골격을 재사용) */
    override?: { bg?: string; fg?: string; radius?: string; accent?: string; accentFg?: string; border?: string; buttons?: 1 | 2 },
  ): React.ReactNode => {
    const ref = spec.styleRef ? specEntries.find((e) => e.name === spec.styleRef) : undefined;
    // AI 의 preview.kind 목록에 없는 형태(체크박스·토글·탭·세그먼트·인풋)는 아키타입 골격으로.
    // 그대로 두면 kind 폴백이 걸려 전부 버튼 모양 막대가 된다.
    if (arch && ARCH_SHAPED.has(arch)) {
      return renderVariantPreview(
        spec.kind,
        {
          // override(대표 변형 색)가 스펙보다 우선 — 스펙 엔트리가 없는 시스템에서 흰 상자로 떨어지는 걸 막는다
          bg: override?.bg ?? resolveSpecValue(ref?.props.backgroundColor),
          fg: override?.fg ?? resolveSpecValue(ref?.props.textColor),
          accent: override?.accent,
          border: resolveSpecValue(ref?.props.borderColor),
          height: resolveSpecValue(ref?.props.height),
          radius: override?.radius ?? (resolveSpecValue(ref?.props.rounded) || resolveSpecValue(ref?.props.radius)),
        },
        spec.label ?? '내용 문구',
        arch,
      );
    }
    const rawBg = override?.bg ?? resolveSpecValue(ref?.props.backgroundColor);
    const bg = rawBg && rawBg !== 'transparent' ? rawBg : pv.primary;
    /** 그라디언트·다중 배경에서 대표 색 하나 — 대비 계산에 쓴다 */
    const bgSolid = solidOf(bg);
    /*
     * 글자 대비는 '실제로 글자가 놓이는 면' 기준이어야 한다. 면을 가진 형태(버튼·칩)는 bg 가
     * 그 면이지만, 카드·패널·행처럼 투명 스펙이 페이지 표면 위에 놓이는 형태는 bg 폴백
     * (pv.primary)이 실제 면이 아니다 — 그대로 계산하면 검정 카드에 #111827 글자가 나온다.
     */
    // 페이지 표면 위에 놓이는 형태만 — bar·bubble·chip 은 bg(=primary 폴백)가 곧 자기 면이다
    const surfaceKind = spec.kind === 'card' || spec.kind === 'panel' || spec.kind === 'row' || spec.kind === 'menu' || spec.kind === 'field';
    const textFace = solidOf(surfaceKind ? (rawBg && rawBg !== 'transparent' ? rawBg : pv.surface) : bg);
    const fgRaw = override?.fg || resolveSpecValue(ref?.props.textColor) || readableOn(textFace) || pv.text;
    // 지정 글자색이 면 위에서 안 읽히면(자료의 fg 가 배경과 밝기가 비슷한 경우) 가독색으로 교정
    const fgGap = contrast(fgRaw, textFace);
    const fg = fgGap !== null && fgGap < 2.2 ? (readableOn(textFace) ?? pv.text) : fgRaw;
    /** 변형이 지정한 테두리 색 — 없으면 기본 헤어라인 */
    const edge = override?.border ? `1px solid ${override.border}` : hair;
    const rawRadius = override?.radius || resolveSpecValue(ref?.props.rounded) || resolveSpecValue(ref?.props.radius) || pv.radiusMd;
    // 알약(999px)·원형 모서리는 버튼·칩에서만 의미가 있다. 표·목록·카드 골격에 그대로 주면
    // 컨테이너 전체가 타원으로 뭉개진다.
    const pillOk = spec.kind === 'button' || spec.kind === 'chip';
    const radiusPx = parseSize(rawRadius);
    // 백분율(50%)은 픽셀 파싱에 안 걸리므로 따로 잡는다 — 안 그러면 표·카드가 타원이 된다
    const tooRound = rawRadius.includes('%') || (radiusPx !== null && radiusPx > 24);
    const radius = tooRound ? (pillOk ? (rawRadius.includes('%') ? '999px' : rawRadius) : '24px') : rawRadius;
    // 빈 문자열도 폴백 — 라벨 없는 빈 알약이 그려지는 걸 막는다
    const label = spec.label || '내용 문구';
    const sub = spec.sub;
    // 변형이 배경은 같고 상태 아이콘 색만 다른 경우(토스트 성공/오류) accent 가 그 차이를 만든다
    const icon = spec.icon ? <DocIcon name={spec.icon} color={override?.accent || fg} /> : null;
    const w = spec.width;

    if (spec.kind === 'button') {
      return (
        <LivePreviewButton
          label={label}
          icon={icon}
          base={{
            display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 8,
            background: bg, color: fg, borderRadius: radius, padding: '12px 26px',
            fontSize: 14, fontWeight: 700, boxSizing: 'border-box', ...(w ? { width: w } : null),
          }}
        />
      );
    }
    if (spec.kind === 'card') {
      return (
        <LiveCardPreview
          box={{ width: w ?? 300, background: rawBg && rawBg !== 'transparent' ? rawBg : pv.surface, color: fg, borderRadius: radius, border: edge, overflow: 'hidden', boxShadow: pv.shadowCard }}
          media={`linear-gradient(135deg, ${pv.primary}, ${pv.surfaceMuted})`}
          title={label}
          sub={sub}
          mutedColor={pv.textMuted}
        />
      );
    }
    if (spec.kind === 'panel') {
      const panelFace = solidOf(rawBg && rawBg !== 'transparent' ? rawBg : pv.surface);
      const btnFace = override?.accent ? solidOf(override.accent) : null;
      const btnGap = btnFace ? contrast(btnFace, panelFace) : null;
      const panelBtnEdge = btnGap !== null && btnGap < 1.35 ? pv.borderC : null;
      // 변형이 준 글자색은 '컴포넌트 면' 기준으로 계산됐다 — 버튼 위에서 안 읽히면 버튼 기준으로 다시
      const accFgGap = override?.accentFg && btnFace ? contrast(solidOf(override.accentFg), btnFace) : null;
      const panelBtnFg = override?.accentFg && (accFgGap === null || accFgGap >= 2.2)
        ? override.accentFg
        : (btnFace ? readableOn(btnFace) ?? onPrimary : onPrimary);
      return (
        <LivePanelPreview
          buttons={override?.buttons ?? 2}
          box={{ width: w ?? 320, background: rawBg && rawBg !== 'transparent' ? rawBg : pv.surface, color: fg, borderRadius: radius, border: edge, padding: 20, boxShadow: pv.shadowCard }}
          title={label}
          sub={sub}
          primary={{
            background: override?.accent ?? pv.primary,
            color: panelBtnFg,
            borderRadius: pv.radiusSm,
            // 흰 버튼이 흰 패널 위에 놓이면 형태가 사라진다 — 면과 대비가 없을 때만 경계선
            ...(panelBtnEdge ? { border: `1px solid ${panelBtnEdge}` } : null),
          }}
          onPrimaryLabel="확인"
          muted={pv.textMuted}
          hair={hair}
        />
      );
    }
    if (spec.kind === 'bubble') {
      return (
        <LiveTooltipPreview
          bubble={{ background: bg, color: fg, borderRadius: radius, padding: '8px 12px', fontSize: 12.5, lineHeight: 1.5, maxWidth: w ?? 220, whiteSpace: 'nowrap' }}
          label={label}
          muted={pv.textMuted}
        />
      );
    }
    if (spec.kind === 'field') {
      return (
        <LiveInput
          placeholder={sub ?? label}
          style={{
            width: w ?? 260, background: rawBg && rawBg !== 'transparent' ? rawBg : pv.surface, color: fg,
            borderRadius: radius, border: edge, padding: '11px 14px', fontSize: 13, boxSizing: 'border-box',
          }}
        />
      );
    }
    if (spec.kind === 'chip') {
      return (
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, background: bg, color: fg, borderRadius: radius, padding: '4px 12px', fontSize: 12, fontWeight: 600 }}>
          {icon}
          {label}
        </span>
      );
    }
    if (spec.kind === 'row') {
      return (
        <LiveRowPreview
          frame={{ width: w ?? 380, border: edge, borderRadius: radius, overflow: 'hidden', background: pv.surface, color: pv.text }}
          header={[label, sub ?? '상태']}
          rows={['첫 번째 항목', '두 번째 항목', '세 번째 항목']}
          activeStyle={{ background: rawBg && rawBg !== 'transparent' ? rawBg : pv.surfaceMuted, color: rawBg && rawBg !== 'transparent' ? fg : onMuted, fontWeight: 700 }}
          muted={pv.textMuted}
        />
      );
    }
    if (spec.kind === 'menu') {
      return (
        <LiveMenuPreview
          box={{ width: w ?? 200, background: pv.surface, borderRadius: radius, border: edge, padding: 6, boxShadow: pv.shadowCard }}
          items={[label, sub ?? '두 번째 항목', '세 번째 항목']}
          activeStyle={{ background: rawBg && rawBg !== 'transparent' ? rawBg : pv.surfaceMuted, color: rawBg && rawBg !== 'transparent' ? fg : onMuted, fontWeight: 700 }}
          idleColor={pv.text}
        />
      );
    }
    // bar (기본) — 토스트·알림 배너: 닫기 → 다시 표시
    return (
      <LiveToastPreview
        box={{ width: w ?? 320, background: bg, color: fg, borderRadius: radius, padding: '12px 16px', display: 'flex', alignItems: 'center', gap: 10, boxShadow: pv.shadowCard, boxSizing: 'border-box' }}
        label={label}
        icon={icon}
        muted={pv.textMuted}
      />
    );
  };

  const renderSpecGrid = (entries: SpecEntry[]) => (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: 14 }}>
      {entries.map((e) => {
        const radius = resolveSpecValue(e.props.rounded) || resolveSpecValue(e.props.radius);
        const meta = [radius && `radius ${radius}`, e.props.height && `h ${e.props.height}`, e.props.padding && !e.props.padding.includes('{') && `p ${e.props.padding}`]
          .filter(Boolean)
          .join(' · ');
        return (
          <div key={e.name} style={{ ...panel, borderRadius: pv.radiusMd, padding: 16 }}>
            <div style={{ ...monoStyle, fontSize: 11.5, color: pv.textMuted, marginBottom: 10 }}>{e.name}</div>
            {renderSpecSample(e)}
            {meta && <div style={{ ...monoStyle, fontSize: 10.5, color: pv.textMuted, marginTop: 10 }}>{meta}</div>}
          </div>
        );
      })}
    </div>
  );

  /** 브랜드 컴포넌트 스펙 — frontmatter components: 맵을 AI 없이 템플릿 렌더 (컴포넌트 그룹 전용 페이지) */
  const renderBrandSpec = () => (
    <div>
      <div style={overline}>COMPONENT</div>
      <h2 style={h2Style}>기타 스펙</h2>
      <p style={sectionDesc}>
        {enrichStalled === false
          ? `AI 가 컴포넌트로 만드는 중인 스펙 ${specAssign.unassigned.length}개예요 — 값은 그대로 렌더한 견본입니다. 끝나면 각자의 페이지로 옮겨가요.`
          : `컴포넌트로 만들어지지 않은 스펙 ${specAssign.unassigned.length}개예요 — 값은 그대로 렌더한 견본입니다. 관리자 화면에서 [AI 보강 다시 실행] 을 누르면 각자의 페이지로 옮겨가요.`}
      </p>
      {specAssign.unassigned.length > 0 && <div style={{ marginBottom: 28 }}>{renderSpecGrid(specAssign.unassigned)}</div>}
      {specRes?.bodyMd && (
        <details>
          <summary style={{ cursor: 'pointer', fontSize: 13, color: pv.textMuted }}>스펙 원문 (YAML)</summary>
          <div style={{ ...panel, borderRadius: pv.radiusLg, padding: '6px 20px', marginTop: 10 }}>
            <Md>{specRes.bodyMd}</Md>
          </div>
        </details>
      )}
    </div>
  );

  /** 코드 없는 컴포넌트 문서 — 이름이 맞물리는 스펙 견본을 상단에, 규칙 산문을 아래에 */
  const renderComponentDoc = (r: GuideItem) => {
    const matched = specAssign.byDoc.get(r.name) ?? []; // LNB 하위 항목과 동일 배정 (단일 소스)
    return (
      <div>
        <div style={overline}>COMPONENT</div>
        <h2 style={h2Style}>{r.title}</h2>
        {matched.length > 0 && (
          <div style={{ margin: '14px 0 24px' }}>{renderSpecGrid(matched)}</div>
        )}
        <div style={{ ...panel, borderRadius: pv.radiusLg, padding: '6px 20px', marginTop: matched.length > 0 ? 0 : 14 }}>
          {/* 컴포넌트로 배정된 조각은 그 페이지에서 보여주므로 여기선 남은 것만 — 중복 회피.
              마커 주석은 IA 신호일 뿐이라 표시 전 제거(react-markdown 이 텍스트로 노출) */}
          <Md>{(docSplit.leftover.get(r.name) ?? []).join('\n\n') || stripMarks(r.bodyMd ?? '')}</Md>
        </div>
      </div>
    );
  };

  const renderDownloads = () => (
    <div>
      <div style={overline}>RESOURCE</div>
      <h2 style={h2Style}>다운로드</h2>
      {previewDraft && (
        <div style={{ ...panel, borderRadius: pv.radiusMd, padding: '14px 18px', fontSize: 13, color: pv.textMuted }}>
          다운로드(DESIGN.md 원문 · AI 스킬 zip)는 발행 후 제공돼요.
        </div>
      )}
      {!previewDraft && (
      <>
      <p style={sectionDesc}>발행 {system.publishedAt ? system.publishedAt.slice(0, 10) : '—'} · 해시 {system.contentHash.slice(0, 12)}</p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: 16 }}>
        <div style={{ ...panel, borderRadius: pv.radiusLg, padding: 20 }}>
          <strong style={{ fontSize: 15 }}>DESIGN.md 원문</strong>
          <p style={{ fontSize: 13, color: pv.textMuted, margin: '6px 0 14px' }}>업로드된 원문 그대로 — 수정 후 재업로드하면 갱신돼요.</p>
          <a
            href={`/api/guide/design-content?name=${encodeURIComponent(system.name)}&raw=1`}
            style={{ display: 'inline-block', border: hair, borderRadius: 999, padding: '6px 14px', fontSize: 13, fontWeight: 700, color: 'inherit', textDecoration: 'none' }}
          >
            ⬇ DESIGN.md
          </a>
        </div>
        <div style={{ ...panel, borderRadius: pv.radiusLg, padding: 20 }}>
          <strong style={{ fontSize: 15 }}>AI 스킬 (.zip)</strong>
          <p style={{ fontSize: 13, color: pv.textMuted, margin: '6px 0 14px' }}>
            토큰 CSS·컴포넌트 코드가 담긴 자급형 스킬 — AI 코딩 도구의 스킬 폴더에 압축을 풀어 사용하세요.
            <br />예: Claude Code 는 프로젝트의 <code style={monoStyle}>.claude/skills/</code> 아래에 풀면 즉시 인식돼요.
          </p>
          <a
            href={`/api/guide/design-content?name=${encodeURIComponent(system.name)}&skill=1`}
            style={{ display: 'inline-block', background: pv.primary, color: onPrimary, borderRadius: 999, padding: '6px 14px', fontSize: 13, fontWeight: 700, textDecoration: 'none' }}
          >
            ⬇ AI 스킬
          </a>
        </div>
      </div>
      </>
      )}
    </div>
  );

  const renderSection = (id: string): React.ReactNode => {
    // 개요 하위 항목(ov-*)은 소개 페이지 안의 섹션이다 — 같은 화면을 그리고 앵커로 이동
    if (id === 'intro' || id.startsWith('ov-')) return renderIntro();
    if (id === 'brand-logo') return renderBrandLogo();
    if (id === 'downloads') return renderDownloads();
    if (id === 'foundation-color') return renderFoundationColor();
    if (id === 'foundation-typography') return renderFoundationTypography();
    if (id === 'foundation-spacing') return renderFoundationSpacing();
    if (id === 'foundation-radius') return renderFoundationRadius();
    if (id === 'foundation-shadow') return renderFoundationShadow();
    if (id.startsWith('foundation-')) return renderFoundationOther(id.slice('foundation-'.length));
    if (id.startsWith('component-')) {
      const c = components.find((x) => `component-${x.name}` === id);
      return c ? renderComponent(c) : renderIntro();
    }
    if (id === 'resource-spec-components' && specRes && specAssign.unassigned.length > 0) return renderBrandSpec();
    if (id.startsWith('resource-')) {
      const r = resources.find((x) => `resource-${x.name}` === id);
      if (!r) return renderIntro();
      return componentDocs.includes(r) ? renderComponentDoc(r) : renderResource(r);
    }
    return renderIntro();
  };

  const flatIndex = flatNav.findIndex((n) => n.id === activeId);
  const prevItem = flatIndex > 0 ? flatNav[flatIndex - 1] : null;
  const nextItem = flatIndex >= 0 && flatIndex < flatNav.length - 1 ? flatNav[flatIndex + 1] : null;

  return (
    <div className="design-guide-scroll" ref={scrollRef}>
      {/* ── 페이지 전체 브랜드 캔버스 — 배경·글자·글꼴부터 토큰 적용 ── */}
      <div style={{ ...tokenVars, background: pv.surface, color: pv.text, fontFamily: pv.font, minHeight: '100%' }}>
        {/* 상단 바 */}
        <header
          ref={topbarRef}
          style={{
            position: 'sticky', top: 0, zIndex: 10, background: pv.surface, borderBottom: hair,
          }}
        >
          <div
            style={{
              maxWidth: 1280, margin: '0 auto', padding: '10px 20px',
              display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap',
            }}
          >
            <button
              onClick={() => navigate('intro')}
              style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'inherit', fontFamily: 'inherit', padding: 0, display: 'flex', alignItems: 'center', gap: 8 }}
            >
              {logoSrc ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img src={logoSrc} alt={system.title} style={{ height: 24, maxWidth: 180, objectFit: 'contain', display: 'block' }} />
              ) : (
                <strong style={{ fontSize: 16, letterSpacing: '-0.01em' }}>{system.title}</strong>
              )}
              <span style={{ ...monoStyle, fontSize: 11.5, color: pv.textMuted }}>v{system.version}</span>
            </button>
            {/* 해시는 상단 미노출 — 정밀 대조는 개요 캡션의 '발행 · 해시' 가 담당 (버전은 수동 선언이라 불충분) */}
            <span style={{ marginLeft: 'auto' }} />
            {hasDark && (
              <div style={{ display: 'flex', border: hair, borderRadius: 999, overflow: 'hidden', fontSize: 12 }}>
                {(['light', 'dark'] as const).map((mode) => (
                  <button
                    key={mode}
                    onClick={() => setDark(mode === 'dark')}
                    aria-label={mode === 'light' ? '라이트 테마' : '다크 테마'}
                    aria-pressed={(mode === 'dark') === dark}
                    style={{
                      padding: '7px 14px', minHeight: 32, border: 'none', cursor: 'pointer',
                      background: (mode === 'dark') === dark ? pv.primary : 'transparent',
                      color: (mode === 'dark') === dark ? onPrimary : 'inherit',
                      fontWeight: (mode === 'dark') === dark ? 700 : 400,
                    }}
                  >
                    {mode === 'light' ? '☀' : '🌙'}
                  </button>
                ))}
              </div>
            )}
            <Link href="/guide/design" style={{ color: pv.textMuted, textDecoration: 'none', fontSize: 12.5 }}>
              ← 목록
            </Link>
          </div>
        </header>

        {previewDraft && (
          <div style={{ background: 'rgba(234,179,8,0.14)', borderBottom: '1px solid rgba(234,179,8,0.4)' }}>
            <div style={{ maxWidth: 1280, margin: '0 auto', padding: '8px 20px', fontSize: 12.5, fontWeight: 600 }}>
              📝 미발행 초안 미리보기 — 발행 전까지 다른 사용자·AI 에게 보이지 않아요. 확인 후 관리자 화면에서 발행하세요.
            </div>
            {/* 업로드 직후엔 AI 보강이 백그라운드로 돈다 — 이 화면만 보면 진행 중인지 알 수 없어 안내 */}
            {pendingDocCount > 0 && enrichStalled === false && (
              <div
                style={{
                  maxWidth: 1280, margin: '0 auto', padding: '0 20px 9px', fontSize: 12.5,
                  display: 'flex', alignItems: 'center', gap: 8,
                }}
              >
                <span className="dgv-pulse" aria-hidden style={{ width: 8, height: 8, borderRadius: '50%', background: '#B45309', flex: 'none' }} />
                <span>
                  설명·변형을 AI 가 채우는 중이에요 — 컴포넌트 {components.length}개 중 {components.length - pendingDocCount}개 완료
                  {specAssign.unassigned.length > 0 ? `, 스펙 ${specAssign.unassigned.length}개는 컴포넌트로 만드는 중` : ''}.
                </span>
                <button
                  type="button"
                  onClick={() => window.location.reload()}
                  style={{
                    border: hair, background: 'transparent', color: 'inherit', fontFamily: 'inherit',
                    borderRadius: 999, padding: '2px 10px', fontSize: 12, fontWeight: 700, cursor: 'pointer',
                  }}
                >
                  지금 확인
                </button>
              </div>
            )}
            {/* 보강이 돌지 않았거나 실패한 상태 — '진행 중' 으로 계속 두면 영영 기다리게 된다 */}
            {pendingDocCount > 0 && enrichStalled === true && (
              <div style={{ maxWidth: 1280, margin: '0 auto', padding: '0 20px 9px', fontSize: 12.5 }}>
                컴포넌트 {components.length}개 중 {pendingDocCount}개가 설명·변형 없이 남아 있어요 — 관리자 화면에서 [AI 보강 다시 실행] 을 눌러 주세요.
              </div>
            )}
          </div>
        )}

        <div
          className="dgv-layout"
          style={{
            maxWidth: 1280, margin: '0 auto', padding: '0 20px',
            // hover 배경은 브랜드 본문색 기반 저알파 틴트 — CSS :hover 가 var 로 소비 (인라인 :hover 불가)
            '--dgv-hover-bg': withAlpha(pv.text, 0.07, 'rgba(148, 163, 184, 0.14)'),
            // 상단 바 실측 높이 — .dgv-sidebar sticky top/max-height 가 소비
            '--dgv-topbar-h': `${topbarH}px`,
          } as React.CSSProperties}
        >
          {/* ── 사이드바 (데이터에서 자동 생성된 IA) ── */}
          {/* 인라인 position 금지 — CSS 의 sticky(데스크톱)를 이겨버려 고정이 죽고 top var 가
              relative 오프셋으로 발동함. 인디케이터 offsetParent 요건은 sticky 도 positioned 라 충족. */}
          <aside ref={sidebarRef} className="dgv-sidebar" style={{ borderColor: pv.borderC }}>
            {/* 활성 인디케이터 — 클릭 시 이전 위치에서 미끄러져 이동 (버튼들이 position:relative 로 위에 얹힘) */}
            {navIndicator && (
              <span
                aria-hidden
                className="dgv-nav-indicator"
                style={{
                  position: 'absolute', top: navIndicator.top, left: navIndicator.left,
                  width: navIndicator.width, height: navIndicator.height,
                  background: pv.surfaceMuted, borderLeft: `3px solid ${pv.primary}`,
                  borderRadius: 8, pointerEvents: 'none',
                }}
              />
            )}
            {navGroups.map((group, gi) => (
              // 그룹 경계: 첫 그룹은 본문 시작 높이와 정렬(여백 0), 이후 그룹은 divider + 고정 간격.
              // position:relative — 슬라이드 중 인디케이터 pill 이 divider·그룹 라벨을 덮지 않게 위로 승격
              <nav key={group.label} className="dgv-nav-group" style={{ position: 'relative', ...(gi > 0 ? { borderTop: hair, marginTop: 16, paddingTop: 14 } : null) }}>
                <div style={{ fontSize: 11.5, fontWeight: 700, letterSpacing: '0.09em', textTransform: 'uppercase', color: textFaint, margin: '0 0 7px', padding: '0 10px' }}>
                  {group.label}
                </div>
                {group.items.map((item, ii) => {
                  const isActive = item.id === activeId;
                  // 소분류가 바뀌는 지점에 라벨 — 컴포넌트 목록이 길어지면 역할 경계가 필요하다
                  const sectionHead =
                    item.section && item.section !== group.items[ii - 1]?.section ? item.section : null;
                  return (
                    <React.Fragment key={item.id}>
                    {sectionHead && (
                      <div
                        style={{
                          fontSize: 11, fontWeight: 700, letterSpacing: '0.06em', color: textFaint,
                          padding: '0 10px', margin: ii === 0 ? '0 0 5px' : '12px 0 5px',
                        }}
                      >
                        {sectionHead}
                      </div>
                    )}
                    <button
                      key={item.id}
                      ref={(el) => { navItemRefs.current[item.id] = el; }}
                      onClick={() => navigate(item.id)}
                      className="dgv-nav-item"
                      style={{
                        display: 'block', width: '100%', textAlign: 'left', cursor: 'pointer',
                        fontSize: 13.5, fontFamily: 'inherit', borderRadius: 8,
                        // 소분류가 있는 항목은 한 단 들여써 라벨과의 위계를 보인다
                        padding: item.section ? '6px 10px 6px 20px' : '6px 10px',
                        border: 'none', marginBottom: 1,
                        // 활성 배경·좌측 바는 인디케이터(단일 pill 슬라이드)가 담당 — 버튼은 글자만.
                        // position:relative 로 인디케이터 위에 얹힘. hover 틴트(CSS)도 그대로 동작.
                        position: 'relative',
                        color: isActive ? onMuted : pv.textMuted,
                        fontWeight: isActive ? 700 : 500,
                        borderLeft: '3px solid transparent',
                        whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
                      }}
                    >
                      {item.label}
                    </button>
                    </React.Fragment>
                  );
                })}
              </nav>
            ))}
          </aside>

          {/* ── 본문 ── */}
          <main className="dgv-main">
            {renderSection(activeId)}

            {/* 이전/다음 */}
            <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12, marginTop: 48, paddingTop: 20, borderTop: hair }}>
              {prevItem ? (
                <button
                  onClick={() => navigate(prevItem.id)}
                  style={{
                    ...panel, borderRadius: pv.radiusMd, padding: '12px 18px', cursor: 'pointer',
                    color: 'inherit', fontFamily: 'inherit', minWidth: 150, maxWidth: '48%',
                    display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 3,
                  }}
                >
                  <span style={{ fontSize: 11.5, color: pv.textMuted, lineHeight: 1 }}>← 이전</span>
                  <span style={{ fontSize: 13.5, fontWeight: 700, lineHeight: 1.3, textAlign: 'left' }}>{prevItem.label}</span>
                </button>
              ) : (
                <span />
              )}
              {nextItem && (
                <button
                  onClick={() => navigate(nextItem.id)}
                  style={{
                    ...panel, borderRadius: pv.radiusMd, padding: '12px 18px', cursor: 'pointer',
                    color: 'inherit', fontFamily: 'inherit', minWidth: 150, maxWidth: '48%', marginLeft: 'auto',
                    display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 3,
                  }}
                >
                  <span style={{ fontSize: 11.5, color: pv.textMuted, lineHeight: 1 }}>다음 →</span>
                  <span style={{ fontSize: 13.5, fontWeight: 700, lineHeight: 1.3, textAlign: 'right' }}>{nextItem.label}</span>
                </button>
              )}
            </div>

            {/* 브랜드 푸터 */}
            <footer style={{ borderTop: hair, marginTop: 28, paddingTop: 22, display: 'flex', justifyContent: 'space-between', gap: 16, flexWrap: 'wrap' }}>
              <div>
                {logoSrc ? (
                  // eslint-disable-next-line @next/next/no-img-element
                  <img src={logoSrc} alt={system.title} style={{ height: 18, maxWidth: 160, objectFit: 'contain', display: 'block' }} />
                ) : (
                  <strong style={{ fontSize: 14.5 }}>{system.title}</strong>
                )}
                <div style={{ fontSize: 12.5, color: pv.textMuted, marginTop: 6 }}>
                  이 페이지 전체가 업로드된 토큰 값으로 렌더된 견본입니다 — 컴포넌트 코드는 실행되지 않아요.
                </div>
              </div>
              <div style={{ display: 'flex', gap: 20, fontSize: 12.5 }}>
                {(
                  [
                    ['가이드', 'intro'],
                    ['토큰', flatNav.find((n) => n.id.startsWith('foundation-'))?.id ?? 'intro'],
                    [
                      '컴포넌트',
                      flatNav.find((n) => n.id.startsWith('component-'))?.id ??
                        (specRes && specAssign.unassigned.length > 0
                          ? 'resource-spec-components'
                          : componentDocs.length > 0 ? `resource-${componentDocs[0].name}` : null),
                    ],
                  ] as Array<[string, string | null]>
                ).map(([label, target]) =>
                  target ? (
                    <button
                      key={label}
                      onClick={() => navigate(target)}
                      className="dgv-foot-link"
                      style={{ background: 'none', border: 'none', padding: 0, cursor: 'pointer', fontFamily: 'inherit', fontSize: 12.5, color: pv.textMuted }}
                    >
                      {label}
                    </button>
                  ) : null,
                )}
              </div>
            </footer>
          </main>
        </div>
      </div>
    </div>
  );
}
